window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[34]={"id":"034","numero":34,"titre":"Suites de couches pathologiques","objectifs":[{"id":"34-1","rang":"B","rubrique":"Dépister","titre":"Connaître les éléments cliniques de surveillance pendant les suites de couches","contenu":"<div class=\"notion-course\"><p>Les <span>suites de couches</span> débutent <strong><span>2 h</span> après l’accouchement</strong> (fin du post-partum immédiat) et se terminent par le <span>retour de couches</span> (= reprise des menstruations). Durée moyenne <span><span class=\"nc-pink_bg\">6 semaines</span></span> (<span><span class=\"nc-pink_bg\">40 jours</span></span>). Une <span>hospitalisation</span> reste possible jusqu’au <span>12ᵉ jour</span> (prise en charge sécurité sociale).</p>\n\n      <p>L’examen quotidien recherche systématiquement les <strong><span <span=\"\">&gt;3</span> grands risques</strong> : <span>hémorragie</span>, <span>hyperthermie</span>, <span>thrombose veineuse</span>.</p>\n\n      <table>\n        <thead>\n          <tr><th>Paramètre</th><th>Ce que l’on cherche</th><th>Alarme si…</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Constantes</strong></td>\n            <td>Température (matin/soir), pouls, PA, FR, SpO₂, diurèse</td>\n            <td>T° &gt; <span>38 °C</span> à 2 reprises, <span>tachycardie</span>, <span>hypotension</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red_bg\">Utérus</span></strong></td>\n            <td>Hauteur utérine (involution ≈ <span>1 cm</span>/j), tonicité (globe de sécurité), sensibilité à la mobilisation</td>\n            <td><span class=\"nc-red_bg\">Utérus</span> <strong><span class=\"nc-red_bg nc-bold\">mal involué</span></strong>, <strong><span class=\"nc-red nc-bold\">mou</span></strong>, <strong>douloureux à la mobilisation</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg\">Lochies</span></strong></td>\n            <td>Quantité, odeur, aspect (sanglantes <span>J1</span>-J3 → séro-sanglantes → séreuses J10)</td>\n            <td><strong><span class=\"nc-yellow_bg nc-bold\">Abondantes</span></strong>, <strong><span class=\"nc-yellow_bg nc-bold\">malodorantes</span> / <span class=\"nc-yellow_bg\">fétides</span></strong>, hémorragiques tardives</td>\n          </tr>\n          <tr>\n            <td><strong>Périnée / cicatrice</strong></td>\n            <td><span class=\"nc-pink nc-bold\">Épisiotomie</span>, déchirures, cicatrice de <span class=\"nc-pink nc-bold\">césarienne</span> (rougeur, écoulement, désunion)</td>\n            <td><span><span class=\"nc-red nc-bold\">Abcès</span></span><span class=\"nc-red nc-bold\"> ou </span><strong><span class=\"nc-red nc-bold\">hématome de paroi</span></strong> après <span class=\"nc-pink nc-bold\">césarienne</span> · <strong>désunion</strong> après <span class=\"nc-pink nc-bold\">épisiotomie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Seins</strong></td>\n            <td>Montée laiteuse (<span>J2</span>-J3), engorgement, crevasses, mise au sein efficace</td>\n            <td><span>Placard</span> <span>inflammatoire</span>, <span>fièvre</span> + douleur localisée (lymphangite, galactophorite, <span>abcès</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Mollets / MI</strong></td>\n            <td>Douleur unilatérale, <span>œdème</span>, Homans, <span>dyspnée</span></td>\n            <td>Signes de <span>TVP</span> ou d’<span>embolie pulmonaire</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mictions / transit</strong></td>\n            <td>Reprise miction spontanée, <span>BU</span> si signes urinaires, reprise du transit</td>\n            <td>Rétention aiguë, <span>BU</span> positive, <span>constipation</span> opiniâtre</td>\n          </tr>\n          <tr>\n            <td><strong>Vécu psy</strong></td>\n            <td><em>Baby-blues</em> (<span>J3</span>-J10, transitoire) · <span>dépistage</span> <span>dépression</span> du post-partum</td>\n            <td>Symptômes durables &gt; <span>15 j</span>, idées suicidaires, troubles du lien mère-enfant</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Mesures préventives systématiques</h4>\n      <ul>\n        <li><strong><span class=\"nc-green_bg\">Lever précoce</span></strong> (<span>J0</span>) — prévention MTEV.</li>\n        <li><strong>Bas de contention</strong> de <span>classe 2</span> chez toutes les accouchées.</li>\n        <li><strong><span>HBPM</span> prophylactique</strong> selon le niveau de risque MTEV (voir obj-6).</li>\n        <li><strong>Ig anti-D</strong> si mère Rh- et enfant Rh+ : <span>200 µg</span> IM dans les <span>72 h</span> post-accouchement.</li>\n        <li><strong>Vaccinations à rattraper</strong> en post-partum : rubéole (si non immune), coqueluche, ROR (CI pendant <span>grossesse</span> mais OK en PP), varicelle.</li>\n        <li><strong>Rééducation périnéale</strong> prescrite à la visite postnatale (<span>6-8 semaines</span>).</li>\n        <li><strong>Contraception du post-partum</strong> proposée avant la sortie (cf. item 31 / 36).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Toute <span>fièvre</span> &gt; <span>38 °C</span>, toute douleur de mollet unilatérale, toute hémorragie ou anomalie des <span class=\"nc-yellow_bg\">lochies</span> en suites de couches doit déclencher <em>immédiatement</em> la triade diagnostique : <strong><span class=\"nc-red_bg nc-bold\">endométrite</span> ? thrombose ? hémorragie ?</strong> Ces 3 entités dominent la morbi-<span>mortalité</span> maternelle du post-partum.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li></ul></details>","frequence":2},{"id":"34-2","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une hyperthermie pendant les suites de couches en fonction de l’étiologie","contenu":"<div class=\"notion-course\"><p>L’<span><span class=\"nc-red nc-bold\">hyperthermie</span></span><span class=\"nc-red nc-bold\"> du post-partum</span> (T° &gt; <span>38 °C</span>) est <strong>fréquente</strong> et impose une démarche étiologique structurée. La <span>montée laiteuse</span> (<span>J2</span>-J3, fébricule modéré, seins tendus bilatéraux, pas d’autre signe) est un <strong>diagnostic d’élimination</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Étiologies à connaître (ordre décroissant)</h4>\n      <table>\n        <thead>\n          <tr><th>Étiologie</th><th>Tableau évocateur</th><th>Confirmation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-red_bg nc-bold\">Endométrite</span> aiguë du PP</span></strong><br><em>1ʳᵉ cause</em></td>\n            <td>\n              <ul>\n                <li>Début <span>J3-J5</span> (rarement avant)</li>\n                <li><span><span class=\"nc-blue_bg nc-bold\">Fièvre</span></span><span class=\"nc-blue_bg nc-bold\"> modérée</span> ≈ <span>38 °C</span></li>\n                <li><strong><span class=\"nc-yellow_bg\">Douleur à la mobilisation utérine</span></strong> ⭐ — signe principal</li>\n                <li><span class=\"nc-blue_bg\">Lochies </span><strong><span class=\"nc-blue_bg\">abondantes et malodorantes</span></strong> (<span class=\"nc-yellow_bg\">fétides</span> ± hémorragiques)</li>\n                <li><span class=\"nc-red_bg\">Utérus</span> <strong><span class=\"nc-red_bg nc-bold\">mal involué</span></strong>, <span class=\"nc-blue_bg\">col béant</span></li>\n                <li><strong>Germes</strong> : infection plurimicrobienne — <span><span class=\"nc-yellow_bg nc-bold\">SGA</span></span> (le + redouté), <span class=\"nc-purple_bg\">entérobactéries</span> (BGN), <span><span class=\"nc-purple_bg\">streptocoque</span></span><span class=\"nc-purple_bg\"> B</span>, <span class=\"nc-purple_bg\">entérocoques</span> ; anaérobies et intracellulaires (mycoplasme, chlamydia) plus rares</li>\n              </ul>\n            </td>\n            <td><span><span class=\"nc-blue_bg\">NFS</span></span><span class=\"nc-blue_bg\">/</span><span><span class=\"nc-blue_bg\">CRP</span></span>, <span><span class=\"nc-blue_bg\">ECBU</span></span>, examen bactério vaginal, <span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span> (<span class=\"nc-orange nc-bold\">rétention</span> ?) · <span><span class=\"nc-red nc-bold\">Hémocultures</span></span> si T° <span class=\"nc-red nc-bold\">&gt; </span><span><span class=\"nc-red nc-bold\">38,5 °C</span></span></td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-purple_bg\">Pyélonéphrite aiguë</span></span></strong> (≠ gravidique)</td>\n            <td>\n              <ul>\n                <li><span>Fièvre</span> + <span>frissons</span></li>\n                <li>Douleur lombaire unilatérale</li>\n                <li>Signes urinaires</li>\n              </ul>\n            </td>\n            <td><span>BU</span>, <span>ECBU</span>, <span><span class=\"nc-blue_bg\">NFS</span></span><span class=\"nc-blue_bg\">/</span><span><span class=\"nc-blue_bg\">CRP</span></span>, <span><span class=\"nc-red nc-bold\">hémocultures</span></span>, écho rénale</td>\n          </tr>\n          <tr>\n            <td><strong><span>Thrombophlébite des MI</span></strong></td>\n            <td>\n              <ul>\n                <li>Douleur de mollet unilatérale</li>\n                <li><span>Œdème</span>, augmentation du <span>diamètre</span></li>\n                <li>Signe de Homans</li>\n                <li><span><span class=\"nc-blue_bg nc-bold\">Fièvre</span></span><span class=\"nc-blue_bg nc-bold\"> modérée</span></li>\n              </ul>\n            </td>\n            <td>Écho-<span>doppler veineux</span> MI · <span>D-dimères</span> <em>peu utiles en PP</em></td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-orange_bg\">Thrombophlébite pelvienne</span></span></strong></td>\n            <td>\n              <ul>\n                <li><span>Fièvre</span> <em>persistante</em> sous ATB d’une endométrite</li>\n                <li><span class=\"nc-blue_bg\">Douleurs pelviennes</span> diffuses</li>\n                <li>Tableau souvent atypique</li>\n              </ul>\n            </td>\n            <td><strong><span>TDM</span> ou <span>IRM</span> pelvienne injectée</strong> — diagnostic de référence</td>\n          </tr>\n          <tr>\n            <td><strong><span>Complications de l’allaitement</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Engorgement</strong> : seins tendus bilatéraux, fébricule</li>\n                <li><strong>Lymphangite</strong> : <span>placard</span> rouge triangulaire, <span>fièvre</span> <span>39-40 °C</span>, ADP axillaire</li>\n                <li><strong>Galactophorite</strong> : douleur, lait <em>louche</em> au signe de Budin</li>\n                <li><strong><span>Abcès</span> du sein</strong> : <span>tuméfaction</span> fluctuante, <span>fièvre</span> élevée</li>\n              </ul>\n            </td>\n            <td>Clinique · <span>échographie</span> mammaire si suspicion d’<span>abcès</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Infection du site opératoire</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Après <span class=\"nc-pink nc-bold\">césarienne</span></strong> : <span><span class=\"nc-red nc-bold\">abcès</span></span><span class=\"nc-red nc-bold\"> ou hématome de paroi</span>, écoulement purulent</li>\n                <li><strong>Après <span class=\"nc-pink nc-bold\">épisiotomie</span></strong> : <strong><span class=\"nc-red nc-bold\">désunion de plaie</span></strong> ± <span class=\"nc-red nc-bold\">hématome périnéal</span></li>\n                <li><span>Alerte</span> : <span>purpura</span> ou décollement cutané rapidement évolutif → rechercher <strong>SGA</strong> ou <strong>S. aureus</strong></li>\n              </ul>\n            </td>\n            <td>Examen clinique, écho de paroi, prélèvements bactério</td>\n          </tr>\n          <tr>\n            <td><span>Montée laiteuse</span> <em>(diagnostic d’élimination)</em></td>\n            <td>Fébricule <span>J2</span>-J3 bilatéral, seins tendus, <strong>pas de douleur utérine, pas de signes urinaires, pas de signes de <span>TVP</span></strong></td>\n            <td>Diagnostic clinique <em>après avoir éliminé les autres causes</em></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Bilan <span>biologique</span> initial systématique</h4>\n      <ul>\n        <li><strong><span>NFS</span> + <span>CRP</span></strong></li>\n        <li><strong><span>BU</span> ± <span>ECBU</span></strong></li>\n        <li><strong>Prélèvement vaginal</strong> (examen bactériologique)</li>\n        <li><strong><span><span class=\"nc-red nc-bold\">Hémocultures</span></span></strong> si T° <span class=\"nc-red nc-bold\">&gt; </span><span><span class=\"nc-red nc-bold\">38,5 °C</span></span> (recherche listeria et SGA notamment)</li>\n        <li><strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span></strong> à la recherche d’une <span class=\"nc-orange nc-bold\">rétention</span> <span class=\"nc-orange nc-bold\">placentaire</span></li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"nc-red_bg nc-bold\">Endométrite</span> à <span class=\"nc-yellow_bg nc-bold\">SGA</span> ⚠️.</strong> <span><span class=\"nc-purple nc-bold\">Streptocoque</span></span><span class=\"nc-purple nc-bold\"> du groupe A</span> <span class=\"nc-yellow_bg\">= germe le plus redouté</span> du post-partum (tableau toxinique pouvant évoluer en quelques heures vers le <span>choc septique</span>). Y penser devant toute <span class=\"nc-red_bg nc-bold\">endométrite</span> d’<span>évolution</span> <span class=\"nc-blue_bg nc-bold\">rapide</span>, <span>hyperthermie</span> élevée, douleurs intenses, signes cutanés. <span><span class=\"nc-red nc-bold\">Hémocultures</span></span> + écouvillonnage vaginal pour test <span class=\"nc-blue_bg nc-bold\">rapide</span>. <span>Hospitalisation</span>, β-lactamines à forte dose ± <span>clindamycine</span>.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Si <span>fièvre</span> persistante sous ATB :</strong> évoquer en priorité <strong>2 diagnostics</strong> →\n        <ul>\n          <li><strong><span class=\"nc-orange_bg\">Thrombophlébite pelvienne</span></strong><span class=\"nc-orange_bg\"> associée</span> (<span><span class=\"nc-blue_bg\">TDM</span></span><span class=\"nc-blue_bg\">/</span><span><span class=\"nc-blue_bg\">IRM</span></span><span class=\"nc-blue_bg\"> injectée</span>).</li>\n          <li><strong><span class=\"nc-orange_bg\">Rétention de fragments placentaires</span></strong> (<span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span>).</li>\n        </ul>\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li></ul></details>","frequence":10},{"id":"34-3","rang":"B","rubrique":"Prise en charge","titre":"Savoir traiter une hyperthermie pendant les suites de couches en fonction de l’étiologie","contenu":"<div class=\"notion-course\"><p>La prise en charge est <strong>étiologique</strong>. <span><span class=\"nc-green_bg\">Hospitalisation</span></span><span class=\"nc-green_bg\"> habituelle</span> pour toute <span>fièvre</span> du post-partum &gt; <span>38,5 °C</span> ou avec <span>signes de gravité</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Endométrite aiguë du PP</h4>\n      <table>\n        <thead><tr><th>Volet</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Orientation</strong></td>\n            <td><span>Hospitalisation</span> 🏥</td>\n          </tr>\n          <tr>\n            <td><strong><span>Antibiothérapie</span></strong></td>\n            <td>\n              <ul>\n                <li><span>Amoxicilline + acide clavulanique</span> pendant <span><span class=\"nc-pink nc-bold\">5-10 jours</span></span></li>\n                <li>Voie IV initialement, relai per os après normalisation thermique</li>\n                <li>Adaptation à l’<span>antibiogramme</span> (prélèvement vaginal, <span><span class=\"nc-red nc-bold\">hémocultures</span></span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Utérotoniques</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-pink nc-bold\">Oxytocine</span></span> ou <span><span class=\"nc-pink nc-bold\">misoprostol</span></span> pour favoriser la rétraction utérine</li>\n                <li><strong>Non systématique</strong>, à débuter en cas d’<strong><span class=\"nc-orange_bg\">endométrite </span><span><span class=\"nc-orange_bg\">hémorragique</span></span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Évolution</span></strong></td>\n            <td>\n              <ul>\n                <li>Généralement rapidement favorable sous traitement adapté</li>\n                <li><strong>Si <span>fièvre</span> persistante</strong> → 2 diagnostics prioritaires :\n                  <ul>\n                    <li><span class=\"nc-orange_bg\">Thrombophlébite pelvienne</span> (<span><span class=\"nc-blue_bg\">TDM</span></span><span class=\"nc-blue_bg\">/</span><span><span class=\"nc-blue_bg\">IRM</span></span><span class=\"nc-blue_bg\"> injectée</span>)</li>\n                    <li><span class=\"nc-orange_bg\">Rétention de fragments placentaires</span> (<span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span>)</li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Autres étiologies — schémas thérapeutiques</h4>\n      <table>\n        <thead><tr><th>Étiologie</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-purple_bg\">Pyélonéphrite</span></span><span class=\"nc-purple_bg\"> aiguë</span></strong></td>\n            <td>\n              <ul>\n                <li>C<span <span=\"\">&gt;3</span>G IV (<span>céfotaxime</span> / <span>ceftriaxone</span>) ± aminoside</li>\n                <li>Relai per os adapté à l’<span>antibiogramme</span> · durée <span>10-14 jours</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Thrombophlébite des MI</strong></td>\n            <td><span>HBPM</span> curative + <span class=\"nc-green_bg\">bas de contention</span> <span>classe 3</span> (cf. obj-6)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Thrombophlébite pelvienne</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>ATB IV adaptée</strong> (poursuite/escalade)</li>\n                <li><strong>Héparinothérapie curative</strong> ± relai <span>AVK</span> selon localisation et étendue</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Engorgement / lymphangite</strong></td>\n            <td>\n              <ul>\n                <li>Poursuite de l’<span>allaitement</span> (sauf <span>abcès</span> patent)</li>\n                <li>Tétées fréquentes, vidange complète, <span>AINS</span> local / <span>paracétamol</span></li>\n                <li>Si lymphangite : ATB anti-staphylococcique (oxacilline, cloxacilline) <span>7-10 jours</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Galactophorite</strong></td>\n            <td>ATB anti-staph + suspension transitoire de l’<span>allaitement</span> du côté atteint</td>\n          </tr>\n          <tr>\n            <td><strong><span>Abcès</span> du sein</strong></td>\n            <td>\n              <ul>\n                <li><strong><span>Drainage</span> chirurgical</strong> ou <span>ponction</span> écho-guidée</li>\n                <li>ATB anti-staphylococcique</li>\n                <li><span>Allaitement</span> <span>contre-indiqué</span> côté atteint pendant la phase aiguë</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Infection de cicatrice de <span class=\"nc-blue_bg\">césarienne</span></strong></td>\n            <td>\n              <ul>\n                <li>Évacuation d’un hématome / mise à plat d’un <span>abcès</span></li>\n                <li>ATB anti-staphylococcique adaptée</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Désunion d’épisiotomie</strong></td>\n            <td>\n              <ul>\n                <li>Soins locaux antiseptiques, cicatrisation dirigée</li>\n                <li><span>Reprise chirurgicale</span> différée si nécessaire</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Montée laiteuse</span></td>\n            <td>Pas d’ATB — <span>surveillance</span> simple, <span>paracétamol</span>, vidange du sein</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Signal d’alarme.</strong> Toute infection cutanée rapidement évolutive avec <strong><span>purpura</span></strong> ou <strong>décollement</strong> doit faire évoquer et traiter en <span>urgence</span> un <span>SGA</span> ou un <span>S. aureus</span> (risque de <span>fasciite nécrosante</span> / <span>sepsis</span> foudroyant) : <span>hospitalisation</span>, β-lactamines IV à forte dose ± <span>clindamycine</span>, avis chirurgical.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li></ul></details>","frequence":0},{"id":"34-4","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","contenu":"<div class=\"notion-course\"><p>Hémorragie du post-partum (HPP) = perte sanguine <span><span class=\"nc-red nc-bold\">≥ 500 mL</span></span><span class=\"nc-red nc-bold\"> ⭐</span>. <strong>1ʳᵉ cause de <span>mortalité</span> maternelle</strong> en France (<span class=\"nc-green nc-bold\">évitable dans </span><span><span class=\"nc-green nc-bold\">80-90 %</span></span><span class=\"nc-green nc-bold\"> des cas</span>). Distinguer 3 fenêtres temporelles :</p>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewbox=\"0 0 560 140\" role=\"img\" aria-label=\"Frise des trois fenêtres temporelles de l&#x27;hémorragie génitale du post-partum : avant 2 heures, hémorragie de la délivrance par atonie utérine (plus de 50 % des cas) ; de 2 à 24 heures, HPP précoce par atonie utérine, rétention placentaire partielle ou plaie de la filière génitale ; de J1 à M3, HPP tardive ou secondaire par endométrite, retour de couches hémorragique ou choriocarcinome avec dosage hCG.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"18\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Hémorragie du post-partum — 3 fenêtres temporelles</text>\n          <rect class=\"fb-red\" x=\"10\" y=\"40\" width=\"172\" height=\"88\" rx=\"6\"></rect>\n          <text class=\"tx-red\" x=\"96\" y=\"61\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\">&lt;<span> 2 h</span></text>\n          <text class=\"tx-red\" x=\"96\" y=\"78\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">Hémorragie de la délivrance</text>\n          <text class=\"tx-red\" x=\"96\" y=\"101\" text-anchor=\"middle\" font-size=\"8.5\">Atonie utérine (&gt;<span> 50 %</span>)</text>\n          <rect class=\"fb-amber\" x=\"194\" y=\"40\" width=\"172\" height=\"88\" rx=\"6\"></rect>\n          <text class=\"tx-amber\" x=\"280\" y=\"61\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\"><span>2 – 24 h</span></text>\n          <text class=\"tx-amber\" x=\"280\" y=\"78\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">HPP précoce</text>\n          <text class=\"tx-amber\" x=\"206\" y=\"94\" font-size=\"8.5\">• Atonie utérine</text>\n          <text class=\"tx-amber\" x=\"206\" y=\"107\" font-size=\"8.5\">• Rétention placentaire</text>\n          <text class=\"tx-amber\" x=\"206\" y=\"120\" font-size=\"8.5\">• Plaie de la filière</text>\n          <rect class=\"fb-amber\" x=\"378\" y=\"40\" width=\"172\" height=\"88\" rx=\"6\"></rect>\n          <text class=\"tx-amber\" x=\"464\" y=\"61\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\"><span>J1</span> – M3</text>\n          <text class=\"tx-amber\" x=\"464\" y=\"78\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">HPP tardive / secondaire</text>\n          <text class=\"tx-amber\" x=\"390\" y=\"94\" font-size=\"8.5\">• Endométrite</text>\n          <text class=\"tx-amber\" x=\"390\" y=\"107\" font-size=\"8.5\">• Retour de couches hém.</text>\n          <text class=\"tx-amber\" x=\"390\" y=\"120\" font-size=\"8.5\">• Choriocarcinome (→ hCG)</text>\n          <line class=\"ln\" x1=\"184\" y1=\"84\" x2=\"191\" y2=\"84\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"194,84 188,80.5 188,87.5\"></polygon>\n          <line class=\"ln\" x1=\"368\" y1=\"84\" x2=\"375\" y2=\"84\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"378,84 372,80.5 372,87.5\"></polygon>\n        </svg>\n        <figcaption>Les bornes datent l’hémorragie — &lt;<span> 2 h</span> délivrance,<span> 2-24 h</span> précoce, &gt;<span> 24 h</span> (J1-M3) tardive — et chaque fenêtre a ses causes propres.</figcaption>\n      </figure>\n\n      <table>\n        <thead>\n          <tr><th>Fenêtre</th><th>Définition</th><th>Causes dominantes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Hémorragie de la délivrance</strong></td>\n            <td>Post-partum immédiat <span>&lt; 2 h</span> après la naissance</td>\n            <td><strong><span><span class=\"nc-yellow_bg\">Atonie utérine</span></span></strong> (&gt; <span>50 %</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>HPP précoce</strong></td>\n            <td>Entre <span>2 h et 24 h</span></td>\n            <td>\n              <ul>\n                <li>Atonie utérine</li>\n                <li><span class=\"nc-orange nc-bold\">Rétention</span> <span class=\"nc-orange nc-bold\">placentaire</span> partielle (cotylédons, membranes)</li>\n                <li><span class=\"nc-orange_bg\">Plaie de la filière génitale</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>HPP tardive / secondaire</strong></td>\n            <td>Entre <span>J1 et M3</span></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-orange_bg\">Endométrite </span><span><span class=\"nc-orange_bg\">hémorragique</span></span></li>\n                <li><span class=\"nc-orange_bg\">Retour de couches </span><span><span class=\"nc-orange_bg\">hémorragique</span></span></li>\n                <li><span><span class=\"nc-orange_bg\">Choriocarcinome</span></span> (rare, justifie un dosage hCG si bilan négatif)</li>\n                <li>Très rares : faux anévrismes, fistules AV, <span class=\"nc-brown_bg\">coagulopathies</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Étiologies — démarche diagnostique</h4>\n\n      <table>\n        <thead>\n          <tr><th>Étiologie</th><th>Clinique</th><th>Paraclinique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-red_bg nc-bold\">Atonie utérine</span></span></strong><br><em>&gt; <span>50 %</span> des HPP</em></td>\n            <td>\n              <ul>\n                <li>Métrorragies abondantes, sang rouge</li>\n                <li><strong><span class=\"nc-red_bg\">Absence de globe de sécurité</span></strong> : <span class=\"nc-red nc-bold\">utérus</span> <span class=\"nc-red nc-bold\">mou</span>, <span class=\"nc-red nc-bold\">non rétracté</span>, <span class=\"nc-red nc-bold\">dépassant l’ombilic</span></li>\n                <li>Pas de <span>fièvre</span>, pas de <span class=\"nc-yellow_bg\">lochies</span> <span class=\"nc-yellow_bg nc-bold\">malodorantes</span></li>\n              </ul>\n            </td>\n            <td><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span> pour <strong>éliminer une <span class=\"nc-orange nc-bold\">rétention</span></strong> (membranes, cotylédons)</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-orange_bg\">Rétention placentaire</span> partielle</span></strong></td>\n            <td>\n              <ul>\n                <li>Pas de signe clinique spécifique ❌</li>\n                <li>Hémorragie persistante malgré utérotoniques</li>\n                <li>Peut favoriser une atonie ou une <span class=\"nc-red_bg nc-bold\">endométrite</span></li>\n              </ul>\n            </td>\n            <td><strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span> ⭐</strong> = examen de référence (systématique si <span>hyperthermie</span> ou hémorragie en PP)</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-orange_bg\">Plaie de la filière génitale</span></span></strong></td>\n            <td>\n              <ul>\n                <li>Saignement <strong>de sang rouge vif</strong></li>\n                <li><span class=\"nc-red nc-bold\">Utérus</span> bien rétracté (globe de sécurité présent)</li>\n                <li>Déchirure du col, du vagin, du périnée</li>\n              </ul>\n            </td>\n            <td><strong>Inspection sous valves</strong> systématique des voies génitales basses</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-orange_bg\">Endométrite hémorragique</span></span></strong></td>\n            <td>\n              <ul>\n                <li>Tableau d’<span class=\"nc-red_bg nc-bold\">endométrite</span> (<span>fièvre</span>, <span class=\"nc-yellow_bg\">douleur à la mobilisation utérine</span>, <span class=\"nc-yellow_bg\">lochies</span> <span class=\"nc-yellow_bg\">fétides</span>)</li>\n                <li>+ saignement génital surajouté</li>\n              </ul>\n            </td>\n            <td><span><span class=\"nc-blue_bg\">NFS</span></span><span class=\"nc-blue_bg\">/</span><span><span class=\"nc-blue_bg\">CRP</span></span>, prélèvement vaginal, écho pelvienne (<span class=\"nc-orange nc-bold\">rétention</span> ?)</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-orange_bg\">Retour de couches hémorragique</span></span></strong></td>\n            <td>\n              <ul>\n                <li>Hémorragie <strong>brutale</strong> <span class=\"nc-pink nc-bold\">plusieurs semaines après l’accouchement</span></li>\n                <li>Cause : carence œstrogénique ou contraception microprogestative précoce</li>\n                <li>Clinique pauvre : apyrétique, indolore, col fermé, <span class=\"nc-green_bg\">utérus involué</span></li>\n              </ul>\n            </td>\n            <td><span><span class=\"nc-blue_bg\">Échographie</span></span> : <span class=\"nc-red_bg\">utérus</span> vide, endomètre fin · élimine <span class=\"nc-red_bg nc-bold\">endométrite</span> ou <span class=\"nc-orange nc-bold\">rétention</span></td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-orange_bg\">Choriocarcinome</span></span></strong></td>\n            <td>Hémorragie tardive <strong>inexpliquée</strong> malgré bilan négatif</td>\n            <td><strong>Dosage hCG</strong> systématique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Bilan paraclinique systématique devant une HPP &gt; <span>2 h</span></h4>\n      <ul>\n        <li><strong><span>NFS</span>, <span>CRP</span>, <span class=\"nc-blue_bg\">bilan d’hémostase</span></strong> (<span>TP</span>, <span>TCA</span>, <span>fibrinogène</span> → <span>CIVD</span> ?)</li>\n        <li><strong>Groupe-rhésus, RAI &lt; <span>3 jours</span></strong></li>\n        <li><strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span></strong></li>\n        <li><strong>Dosage hCG</strong> si hémorragie tardive inexpliquée (<span class=\"nc-orange_bg\">choriocarcinome</span>)</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong><span>Facteurs de risque</span> d’HPP — dogme.</strong> Aucun facteur retrouvé dans <span><span class=\"nc-pink nc-bold\">50 %</span></span><span class=\"nc-pink nc-bold\"> des cas</span> : <em>aucun accouchement n’est « à bas risque »</em>.<br>\n        <strong><span>Terrain</span></strong> : <span class=\"nc-blue_bg\">grande multiparité</span>, <span class=\"nc-blue_bg\">utérus cicatriciel</span>, ATCD HPP.<br>\n        <strong><span>Grossesse</span></strong> : surdistension (macrosomie, hydramnios, gémellaire), <span class=\"nc-orange_bg\">fibromes</span>, <span class=\"nc-orange_bg\">placenta praevia</span>, <span class=\"nc-purple_bg\">chorioamniotite</span>.<br>\n        <strong>Accouchement</strong> : <span class=\"nc-blue_bg\">travail</span> <span class=\"nc-blue_bg nc-bold\">déclenché</span>, <span class=\"nc-blue_bg nc-bold\">très</span> <span class=\"nc-blue_bg nc-bold\">rapide</span> ou <span class=\"nc-blue_bg nc-bold\">prolongé</span>, <span class=\"nc-pink nc-bold\">épisiotomie</span> / déchirure périnéale, forceps / ventouse, absence d’utérotoniques systématiques.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li></ul></details>","frequence":0},{"id":"34-5","rang":"B","rubrique":"Prise en charge","titre":"Savoir traiter une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","contenu":"<div class=\"notion-course\"><p>Toute HPP est une <span>urgence vitale</span>. La prise en charge est <strong>simultanément maternelle (hémodynamique)</strong> et <strong>obstétricale (geste hémostatique)</strong>, escaladée par paliers de 15-<span <span=\"\">&gt;<span class=\"nc-pink nc-bold\">30</span></span><span class=\"nc-pink nc-bold\"> minutes</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Hémorragie de la délivrance (post-partum immédiat &lt; <span>2 h</span>)</h4>\n      <table>\n        <thead><tr><th>Temps</th><th>Actions</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1ᵉʳ temps</strong></td>\n            <td>Prévenir <strong>tous les intervenants</strong> (anesthésiste, sage-femme, obstétricien) sans délai</td>\n          </tr>\n          <tr>\n            <td><strong>2ᵉ temps</strong></td>\n            <td>\n              <ul>\n                <li>Monitorage (pouls, PA, SpO₂)</li>\n                <li>VVP de gros calibre, remplissage cristalloïdes</li>\n                <li>Vérification groupe + RAI &lt; <span>3 jours</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3ᵉ temps — geste obstétrical</strong></td>\n            <td>\n              <ul>\n                <li>Si hémorragie <strong>avant</strong> expulsion du placenta → <strong><span class=\"nc-yellow_bg\">délivrance artificielle</span></strong><span class=\"nc-yellow_bg\"> en </span><span><span class=\"nc-yellow_bg\">urgence</span></span></li>\n                <li>Si hémorragie <strong>après</strong> expulsion → <strong><span class=\"nc-pink nc-bold\">révision utérine</span></strong> d’emblée</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>4ᵉ temps — hémostase</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-green_bg\">Massage utérin énergique</span> ⭐</strong> jusqu’à obtenir un <strong><span class=\"nc-green nc-bold\">globe tonique</span></strong></li>\n                <li><strong>Inspection sous valves</strong> → éliminer une déchirure cervicale / vaginale</li>\n                <li><span>Oxytocine IVL 10 UI</span>, renouvelable 1×</li>\n                <li>Sac collecteur sous les fesses (estimation des pertes)</li>\n                <li><span class=\"nc-green_bg\">Sondage urinaire à demeure</span> (vessie vide = bon globe)</li>\n                <li><span class=\"nc-green_bg\">Suture des déchirures périnéales éventuelles</span></li>\n                <li><span><span class=\"nc-pink_bg\">Antibioprophylaxie</span></span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Si persistance des saignements à <span>15-30 min</span> :</strong>\n        <ul>\n          <li><span>Sulprostone</span> (prostaglandine) à la seringue électrique, puis relai <span class=\"nc-pink nc-bold\">oxytocine</span> <span>2 h</span></li>\n          <li><span>Acide tranexamique</span> <span>1 g</span> IV</li>\n          <li>VVP gros calibre, <span>oxygénothérapie</span>, remplissage par macromolécules</li>\n          <li><strong>Transfusion CGR + PFC</strong> selon pertes et coagulation</li>\n          <li><span>NFS</span> + <span class=\"nc-blue_bg\">bilan d’hémostase</span> en <span>urgence</span> (recherche <span>CIVD</span>)</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>Si hémorragie persistante malgré la PEC initiale :</strong>\n        <ul>\n          <li><strong>Embolisation artérielle sélective</strong> — 3 prérequis : patiente stable, <span class=\"nc-green_bg\">radiologue entraîné disponible</span>, unité d’embolisation à proximité</li>\n          <li><strong><span>Chirurgie</span></strong> : <span class=\"nc-pink_bg nc-bold\">ligature</span> des artères utérines / hypogastriques, <span class=\"nc-pink_bg\">techniques de</span> compression utérine (B-Lynch, Cho)</li>\n          <li><strong>En dernier recours — <span class=\"nc-red_bg\">hystérectomie d’hémostase</span></strong>, à ne pas retarder si <span><span class=\"nc-red nc-bold\">hémodynamique instable</span></span> ou <span><span class=\"nc-red nc-bold\">CIVD installée</span></span></li>\n        </ul>\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Hémorragies du post-partum (&gt; <span>2 h</span>) — traitement étiologique</h4>\n      <table>\n        <thead><tr><th>Étiologie</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Atonie utérine</strong></td>\n            <td>\n              <ul>\n                <li>Massage utérin + <span>utérotoniques</span> (<span class=\"nc-pink nc-bold\">oxytocine</span>, prostaglandines)</li>\n                <li>Si échec → escalade comme HPP de la délivrance</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-purple_bg\">Rétention placentaire</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-yellow_bg\">Révision utérine prudente</span></strong> (curette mousse sous contrôle échographique — <span class=\"nc-red_bg\">utérus</span> fragile)</li>\n                <li><span class=\"nc-pink_bg\">Résection hystéroscopique</span> parfois</li>\n                <li><strong><span>Antibioprophylaxie</span></strong> systématique</li>\n                <li>Si hémorragie importante : <strong><span class=\"nc-pink nc-bold\">tamponnement intra-utérin</span></strong> (Bakri) ou embolisation</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Plaie de la filière génitale</span></strong></td>\n            <td>Suture après exposition sous valves, au bloc si nécessaire</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Endométrite </span><span><span class=\"nc-orange_bg\">hémorragique</span></span></strong></td>\n            <td>\n              <ul>\n                <li><span>Amoxicilline + acide clavulanique</span> IV</li>\n                <li><strong>Utérotoniques systématiques</strong> (<span class=\"nc-pink nc-bold\">oxytocine</span> ± <span class=\"nc-pink nc-bold\">misoprostol</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Retour de couches </span><span><span class=\"nc-orange_bg\">hémorragique</span></span></strong></td>\n            <td>\n              <ul>\n                <li>Pilule œstrogénique (en l’absence de CI)</li>\n                <li><span>Surveillance</span> simple si pertes modérées</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Choriocarcinome</span></strong></td>\n            <td>Dosage hCG → orientation oncologique spécialisée (<span>chimiothérapie</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Prévention systématique de l’HPP — APO.</strong> <span><span class=\"nc-pink nc-bold\">Oxytocine</span> 5-10 UI IVL</span> dès la sortie de l’enfant, sac de recueil dès l’expulsion, <span>surveillance</span> <span>2 h</span> en salle de <span class=\"nc-blue_bg\">travail</span>, <span class=\"nc-pink nc-bold\">délivrance artificielle</span> si non-décollement <span class=\"nc-orange nc-bold\">placentaire</span> à <span>30 min</span>.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li></ul></details>","frequence":1},{"id":"34-6","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","contenu":"<div class=\"notion-course\"><p>Le post-partum est un <strong><span>facteur de risque</span> transitoire majeur de MTEV</strong>, surtout pendant les <span>8 premières semaines</span>. Quatre formes cliniques à reconnaître.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Facteurs favorisants</h4>\n      <ul>\n        <li><span class=\"nc-pink_bg\">Âge </span><span><span class=\"nc-pink_bg\">&gt; 35 ans</span></span>, <span class=\"nc-red nc-bold\">multiparité</span>, <span>tabac</span></li>\n        <li><span><span class=\"nc-pink_bg\">Obésité</span></span>, <span class=\"nc-pink_bg\">varices</span>, affections cardiaques</li>\n        <li>ATCD personnel de MTEV, thrombophilie</li>\n        <li>Accouchement dystocique ou <strong>césarienne</strong> (surtout en <span>urgence</span>)</li>\n        <li><span class=\"nc-pink_bg\">Procréation médicalement assistée</span></li>\n        <li><strong>Hémorragie du post-partum</strong></li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Formes cliniques</h4>\n      <table>\n        <thead>\n          <tr><th>Forme</th><th>Tableau évocateur</th><th>Examen de référence</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Thrombose veineuse superficielle</span></strong></td>\n            <td>\n              <ul>\n                <li>Cordon induré douloureux sur trajet variqueux</li>\n                <li>Inflammation locale, pas de <span>fièvre</span> élevée</li>\n              </ul>\n            </td>\n            <td>Clinique · écho-<span>doppler veineux</span> (élimine extension profonde)</td>\n          </tr>\n          <tr>\n            <td><strong><span>Thrombose veineuse profonde (MI)</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Douleur de mollet unilatérale</strong></li>\n                <li><span>Œdème</span>, augmentation du <span>diamètre</span>, perte du ballant</li>\n                <li>Signe de Homans</li>\n                <li>Fébricule modéré, <span>tachycardie</span> inexpliquée</li>\n              </ul>\n            </td>\n            <td><strong>Écho-<span>doppler veineux</span> des MI</strong> · <span>D-dimères</span> <em>peu utiles en PP</em> (élevés physiologiquement)</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-orange_bg\">Thrombophlébite pelvienne</span></span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span>Fièvre</span> persistante</strong> sous ATB pour endométrite</li>\n                <li><span class=\"nc-blue_bg\">Douleurs pelviennes</span> / lombo-abdominales diffuses</li>\n                <li>Tableau atypique, retardé</li>\n              </ul>\n            </td>\n            <td><strong><span>TDM</span> ou <span>IRM</span> pelvienne injectée</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span>Thrombose veineuse cérébrale</span></strong></td>\n            <td>\n              <ul>\n                <li><span>Céphalées</span> inhabituelles, persistantes</li>\n                <li>Crises convulsives, déficit focal</li>\n                <li>Troubles de la conscience, signes d’<span>HTIC</span></li>\n              </ul>\n            </td>\n            <td><strong><span>IRM</span> cérébrale + <span>angio-IRM</span> veineuse</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Complication redoutée — <span>embolie pulmonaire</span></h4>\n      <ul>\n        <li><span>Dyspnée</span> brutale, <span>douleur thoracique</span>, <span>tachycardie</span>, hypoxémie</li>\n        <li><span>Toute dyspnée du post-partum est une EP jusqu’à preuve du contraire</span></li>\n        <li>Confirmation : <strong><span>angio-TDM</span> thoracique</strong> (scinti V/Q si CI)</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Piège diagnostique.</strong> En post-partum, les <strong><span>D-dimères</span></strong> sont physiologiquement élevés et n’ont <em>pas de valeur d’exclusion</em>. La décision diagnostique repose donc directement sur la <strong>probabilité clinique + imagerie</strong> (écho-<span>doppler veineux</span>, <span>angio-TDM</span>).\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li></ul></details>","frequence":1},{"id":"34-7","rang":"B","rubrique":"Prise en charge","titre":"Savoir traiter une thrombose veineuse dans le post-partum en fonction de l’étiologie","contenu":"<div class=\"notion-course\"><p>Deux axes : <strong>prophylaxie</strong> (stratifiée selon le niveau de risque MTEV) et <strong>traitement curatif</strong> (selon la localisation).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">A. Prophylaxie de la MTEV en post-partum</h4>\n      <table>\n        <thead>\n          <tr><th>Niveau de risque</th><th>Définition</th><th>Prophylaxie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Risque majeur</span></strong></td>\n            <td>\n              <ul>\n                <li>ATCD de <strong><span class=\"nc-red nc-bold\">MTEV multiples</span></strong></li>\n                <li><strong><span class=\"nc-red nc-bold\">Thrombophilie traitée au long cours</span></strong> par <span>anticoagulant</span> (même avant la <span>grossesse</span>)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Bas de contention</span></li>\n                <li><strong><span>AVK</span> pendant <span class=\"nc-pink nc-bold\">≥ </span><span><span class=\"nc-pink nc-bold\">3 mois</span></span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risque élevé</strong></td>\n            <td>\n              <ul>\n                <li>ATCD MTEV sans FR retrouvé</li>\n                <li>ATCD MTEV lors d’une <span>grossesse</span> antérieure ou d’un traitement œstrogénique</li>\n                <li>ATCD MTEV + 1 FR <span>biologique</span> (déficit AT, <span class=\"nc-red\">SAPL</span>, mutation <span class=\"nc-red\">20210A</span> homozygote ou <span>FV</span> <span class=\"nc-red\">Leiden</span>, anomalies hétérozygotes combinées)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Bas de contention</span></li>\n                <li><strong><span><span class=\"nc-pink nc-bold\">HBPM</span></span><span class=\"nc-pink nc-bold\"> à dose prophylactique forte</span></strong> pendant <span>6-8 semaines</span><br><em><span>énoxaparine</span> 4 <span>000 UI</span>/j ou daltéparine 5 <span>000 UI</span>/j</em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risque modéré</strong></td>\n            <td>\n              <ul>\n                <li>ATCD MTEV avec FR temporaire au moment de l’épisode antérieur</li>\n                <li>ATCD MTEV + FR <span>biologique</span> (autre que ceux du risque élevé)</li>\n                <li>FR <span>biologique</span> asymptomatique dépisté dans le cadre d’une MTEV familiale</li>\n                <li><strong><span class=\"nc-pink_bg\">Césarienne en </span><span><span class=\"nc-pink_bg\">urgence</span></span></strong></li>\n                <li>Césarienne + <span>chirurgie</span> pelvienne majeure associée</li>\n                <li>Présence de ≥ <span>3 FR faibles</span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Bas de contention</span></li>\n                <li><strong><span>HBPM</span> à dose prophylactique forte</strong> pendant <span>6-8 semaines</span> (dose et durée pouvant être réduites selon le niveau de risque)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risque faible</strong></td>\n            <td>\n              &lt; 3 des FR suivants :\n              <ul>\n                <li><span class=\"nc-pink_bg\">Âge &gt;</span><span><span class=\"nc-pink_bg\"> 35 ans</span></span>, <span><span class=\"nc-pink_bg\">obésité</span></span> (IMC &gt; 30 ou poids &gt;<span> 80 kg</span>), <span class=\"nc-pink_bg\">varices</span>, <span><span class=\"nc-pink_bg\">HTA</span></span></li>\n                <li>Facteurs obstétricaux : <span class=\"nc-blue_bg\">césarienne</span>, <span class=\"nc-blue_bg\">multiparité &gt; 4</span>, <span class=\"nc-blue_bg\">prééclampsie</span>, <span class=\"nc-blue_bg\">alitement strict prolongé</span>, HPP…</li>\n                <li><span class=\"nc-orange_bg\">Maladie thrombogène sous-jacente</span> (<span>syndrome néphrotique</span>, <span>MICI</span> en poussée, infection systémique…)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Bas de contention</span></li>\n                <li><strong>Pas d’<span>anticoagulant</span></strong> ❌</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">B. Traitement curatif selon la localisation</h4>\n      <table>\n        <thead><tr><th>Localisation</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Thrombose veineuse superficielle</strong></td>\n            <td>\n              <ul>\n                <li><span>AINS</span> locaux + <span class=\"nc-green_bg\">contention veineuse</span></li>\n                <li>± <span class=\"nc-pink_bg\">Anticoagulation</span> selon extension et localisation</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Thrombose veineuse profonde</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-pink_bg\">Anticoagulation</span> curative</strong> (<span>HBPM</span>, puis relai <span>AVK</span> compatible avec l’<span>allaitement</span>)</li>\n                <li><span class=\"nc-green_bg\">Contention veineuse</span> <strong><span>classe 3</span></strong></li>\n                <li>Durée : <span>3-6 mois</span> minimum selon contexte</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Thrombophlébite pelvienne</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-pink_bg\">ATB IV adaptée</span></strong></li>\n                <li><strong>Héparinothérapie curative</strong> ± relai <span>AVK</span> selon localisation et étendue</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Thrombose veineuse cérébrale</strong></td>\n            <td>\n              <ul>\n                <li><strong><span>HBPM</span> curative</strong> puis relai <span><span class=\"nc-pink_bg\">AVK</span></span> ≥ <span>6 mois</span></li>\n                <li><span class=\"nc-pink_bg\">± mannitol / anti-épileptique</span> selon signes neurologiques</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">C. Choix de l’<span>AVK</span> pendant l’<span>allaitement</span></h4>\n      <table>\n        <thead><tr><th>Molécule</th><th>Allaitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span><span class=\"nc-red nc-bold\">Fluindione</span></span></td>\n            <td><span>❌ Contre-indiquée</span> — non utilisable pendant l’<span>allaitement</span></td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-pink_bg\">Warfarine</span></span>, <span><span class=\"nc-pink_bg\">acénocoumarol</span></span></td>\n            <td>✅ Possibles — pas de <span>diffusion</span> dans le lait maternel</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> En post-partum la <strong><span><span class=\"nc-pink_bg\">warfarine</span></span></strong> et l’<strong><span class=\"nc-pink_bg\">acénocoumarol</span></strong> sont les <span><span class=\"nc-pink_bg\">AVK</span></span> de choix si <span>allaitement</span>, jamais la <span><span class=\"nc-red nc-bold\">fluindione</span></span>. Les <span>HBPM</span> restent l’option la plus utilisée en pratique en relai initial.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Hémorragies du post-partum, 2014</a></li><li><a href=\"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download\" target=\"_blank\" rel=\"noopener noreferrer\">OMS · Acide tranexamique et HPP, 2017</a></li></ul></details>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Hémorragie du post-partum immédiat <span class=\"q\">— &lt;<span class=\"kw-chiffre\"> 2 h</span>, <span class=\"kw-alerte\">urgence</span> vitale</span></strong></p><p>Appel de tous les intervenants sans délai · massage utérin · <span class=\"kw-ttt\">oxytocine IVL 10 UI</span> · escalade par paliers de <span class=\"kw-chiffre\">15-30 min</span></p><ul><li><strong>1ʳᵉ cause de <span class=\"kw-def\">mortalité</span> maternelle</strong> en France (<span class=\"kw-chiffre\">80-90 %</span> évitable)</li><li>Perte sanguine <span class=\"kw-chiffre\">≥ 500 mL</span> → diagnostic</li><li><span class=\"kw-alerte\">Atonie utérine</span> = cause dans <span class=\"kw-chiffre\">&gt; 50 %</span> des cas</li></ul><p><strong>Persistance de l'hémorragie à <span class=\"kw-chiffre\">15-30 min</span></strong></p><p>Si persistance → <strong>embolisation artérielle sélective</strong> (patiente stable) ou <span class=\"kw-ttt\">chirurgie</span> (ligature, compression B-Lynch) · dernier recours : <span class=\"kw-alerte\">hystérectomie d'hémostase</span></p><ul><li><span class=\"kw-ttt\">Sulprostone</span> (seringue électrique) + relai <span class=\"kw-ttt\">oxytocine</span> <span class=\"kw-chiffre\">2 h</span></li><li><span class=\"kw-ttt\">Acide tranexamique</span> <span class=\"kw-chiffre\">1 g</span> IV</li><li>Transfusion <span class=\"kw-ttt\">CGR + PFC</span> si besoin · recherche <span class=\"kw-bio\">CIVD</span></li></ul><p><strong>Endométrite à <span class=\"kw-etio\">SGA</span> <span class=\"q\">— germe le plus redouté</span></strong></p><p><span class=\"kw-ttt\">β-lactamines IV à forte dose</span> ± <span class=\"kw-ttt\">clindamycine</span> ; <span class=\"kw-bio\">hémocultures</span> + test rapide SGA ; avis chirurgical si <span class=\"kw-alerte\">fasciite nécrosante</span> suspectée</p><ul><li>Tableau <span class=\"kw-alerte\">toxinique fulminant</span> en quelques heures</li><li><span class=\"kw-clinique\">Hyperthermie élevée</span> + douleurs intenses + signes cutanés</li><li>Risque de <span class=\"kw-alerte\">choc septique</span></li></ul>","hospit":"<p><strong><span class=\"kw-alerte\">Hospitalisation</span> systématique</strong> pour toute <span class=\"kw-clinique\">fièvre</span> du post-partum &gt; <span class=\"kw-chiffre\">38,5 °C</span> ou avec <span class=\"kw-alerte\">signes de gravité</span>.<br><strong>Maternité :</strong> endométrite, HPP (tous niveaux) → prise en charge sur place (obstétricien + anesthésiste + sage-femme disponibles).<br><strong><span class=\"kw-def\">Surveillance</span> <span class=\"kw-chiffre\">2 h</span> en salle de travail</strong> : systématique après tout accouchement, avant tout retour en chambre.<br><strong>Thrombose veineuse cérébrale</strong> : transfert en neurologie/<span class=\"kw-alerte\">réanimation</span> avec <span class=\"kw-imagerie\">IRM cérébrale + angio-IRM</span> veineuse.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Hémorragie &gt; 500 mL</span> ou absence de globe de sécurité utérin</li><li><span class=\"kw-alerte\">Instabilité hémodynamique</span> : <span class=\"kw-clinique\">hypotension</span>, tachycardie, pâleur, <span class=\"kw-clinique\">sueurs</span></li><li><span class=\"kw-alerte\">Fièvre persistante sous ATB</span> → évoquer thrombophlébite pelvienne ou rétention placentaire</li><li><span class=\"kw-alerte\">Purpura ou décollement cutané rapidement évolutif</span> → SGA / S. aureus (<span class=\"kw-alerte\">fasciite nécrosante</span>)</li><li><span class=\"kw-alerte\">Dyspnée brutale</span> en post-partum → <span class=\"kw-alerte\">embolie pulmonaire</span> jusqu'à preuve du contraire</li><li><span class=\"kw-alerte\">Céphalées inhabituelles</span> + <span class=\"kw-alerte\">convulsions</span> + déficit focal → thrombose veineuse cérébrale</li><li><span class=\"kw-alerte\">CIVD installée</span> : allongement <span class=\"kw-bio\">TP/TCA</span>, effondrement du <span class=\"kw-bio\">fibrinogène</span></li></ul>","principes":"<p>Démarche <strong>étiologique</strong> obligatoire. Trois axes principaux : traitement de l'<span class=\"kw-etio\">hémorragie</span>, traitement de l'<span class=\"kw-clinique\">hyperthermie</span>, traitement de la <span class=\"kw-def\">MTEV</span>.</p><p><strong>Endométrite aiguë</strong></p><ul><li><span class=\"kw-ttt\">Amoxicilline + acide clavulanique</span> IV pendant <span class=\"kw-chiffre\">5-10 jours</span> (relai per os après normalisation thermique)</li><li><span class=\"kw-ttt\">Utérotoniques</span> (oxytocine, misoprostol) si endométrite <span class=\"kw-etio\">hémorragique</span></li></ul><p><strong>HPP — traitement étiologique (&gt; <span class=\"kw-chiffre\">2 h</span>)</strong></p><ul><li>Atonie : massage utérin + <span class=\"kw-ttt\">utérotoniques</span> · escalade si échec</li><li>Rétention placentaire : révision utérine prudente + <span class=\"kw-ttt\">antibioprophylaxie</span></li><li>Retour de couches <span class=\"kw-etio\">hémorragique</span> : <span class=\"kw-ttt\">pilule œstrogénique</span> (en l'absence de <span class=\"kw-ci\">CI</span>)</li></ul><p><strong>MTEV curative</strong></p><ul><li>TVP des MI : <span class=\"kw-ttt\">HBPM curative</span> + contention <span class=\"kw-chiffre\">classe 3</span> · durée <span class=\"kw-chiffre\">3-6 mois</span></li><li>Thrombophlébite pelvienne : <span class=\"kw-ttt\">ATB IV</span> adaptée + <span class=\"kw-ttt\">héparinothérapie curative</span> ± relai <span class=\"kw-ttt\">AVK</span></li><li>TVC : <span class=\"kw-ttt\">HBPM</span> puis relai <span class=\"kw-ttt\">AVK ≥ 6 mois</span> ± mannitol / anti-épileptique</li><li><span class=\"kw-ci\">Fluindione contre-indiquée</span> pendant l'<span class=\"kw-ci\">allaitement</span> — préférer <span class=\"kw-ttt\">warfarine</span> ou <span class=\"kw-ttt\">acénocoumarol</span></li></ul>","suivi":"<p><strong>Post-partum immédiat :</strong> <span class=\"kw-def\">surveillance</span> <span class=\"kw-chiffre\">2 h</span> en salle de travail (<span class=\"kw-clinique\">FC</span> · <span class=\"kw-clinique\">PA</span> · globe utérin · lochies · diurèse).<br><strong>Endométrite :</strong> normalisation thermique attendue <span class=\"kw-chiffre\">48-72 h</span> sous ATB ; si <span class=\"kw-clinique\">fièvre</span> persistante → <span class=\"kw-imagerie\">TDM/IRM</span> pelvienne + <span class=\"kw-imagerie\">échographie</span> (thrombophlébite pelvienne ou rétention ?).<br><strong>Visite postnatale</strong> à <span class=\"kw-chiffre\">6-8 semaines</span> : examen périnéal, prescription <span class=\"kw-ttt\">rééducation périnéale</span>, contraception, <span class=\"kw-def\">dépistage</span> <span class=\"kw-def\">dépression post-partum</span> (EPDS).<br><strong>MTEV :</strong> contrôle écho-<span class=\"kw-imagerie\">doppler veineux</span> à la fin du traitement <span class=\"kw-ttt\">anticoagulant</span>.</p>"},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"urgent","label":"Hémorragie ou mauvaise tolérance","detail":"<ul><li>Quantifier sans attendre un seuil si choc ; alerte et chronométrage.</li></ul>","branches":[{"label":"Réanimation et recherche de cause","to":"causes"}]},{"id":"causes","kind":"decision","label":"Tone, Tissue, Trauma, Thrombin","detail":"<ul><li>Voies veineuses, bilan, sang disponible ; rechercher atonie, rétention, lésions et coagulopathie.</li></ul>","branches":[{"label":"Rétention / lésions","to":"geste"},{"label":"Atonie","to":"uterus"},{"label":"Coagulopathie","to":"coag"}]},{"id":"geste","kind":"decision","label":"Contrôle obstétrical de la cause","detail":"<ul><li>Délivrance/révision, exploration et suture selon indication.</li></ul>","branches":[{"label":"Saignement persistant","to":"escalade"},{"label":"Contrôle obtenu","to":"suivi"}]},{"id":"uterus","kind":"decision","label":"Massage et utérotoniques","detail":"<ul><li>Oxytocine, puis deuxième ligne selon protocole ; tranexamique précoce dans les 3 h.</li></ul>","branches":[{"label":"Saignement persistant","to":"escalade"},{"label":"Contrôle obtenu","to":"suivi"}]},{"id":"coag","kind":"decision","label":"Corriger la coagulopathie","detail":"<ul><li>Transfusion guidée par clinique et biologie, en contrôlant la cause.</li></ul>","branches":[{"label":"Persistance","to":"escalade"},{"label":"Contrôle","to":"suivi"}]},{"id":"escalade","kind":"urgent","label":"Ballon, embolisation ou chirurgie","detail":"<ul><li>Selon cause et stabilité ; ne pas retarder chirurgie/hystérectomie de sauvetage.</li></ul>","branches":[]},{"id":"suivi","kind":"finish","label":"Surveillance, anémie et débriefing","detail":"<ul><li>Risque de récidive, récupération, prévention prochaine naissance.</li></ul>","branches":[]}]},"cards":[{"i":"3338deabf3ff","n":34,"o":"34-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","q":"Quels sont les éléments cliniques et paracliniques suggestifs d'une endométrite hémorragique comme cause d'HPP tardive ?","a":"<div class=\"notion-course\"><ul><li><strong>Clinique :</strong> tableau d'<span class=\"nc-red_bg nc-bold\">endométrite</span> <span class=\"nc-red_bg\">avec</span> <strong>fièvre</strong>, <strong><span class=\"nc-yellow_bg\">douleur à la mobilisation utérine</span></strong>, <strong><span class=\"nc-yellow_bg\">lochies</span> <span class=\"nc-yellow_bg\">fétides</span></strong>, auxquels s'ajoute un saignement génital.</li><li><strong>Paraclinique :</strong> une <strong><span class=\"nc-blue_bg\">NFS/CRP</span></strong>, un <strong>prélèvement vaginal</strong> et une <strong><span class=\"nc-blue_bg\">échographie pelvienne</span></strong> (pour rechercher une <span class=\"nc-orange nc-bold\">rétention</span>) sont réalisés.</li></ul></div>"},{"i":"53583d2f59fe","n":34,"o":"34-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","q":"Dans le contexte d'une hémorragie tardive inexpliquée après l'accouchement, quel dosage paraclinique doit être systématiquement réalisé et pourquoi ?","a":"<div class=\"notion-course\"><p>Un <strong>dosage de l'hCG</strong> (hormone chorionique gonadotrophine) doit être systématiquement réalisé afin d'éliminer la piste d'un <strong><span class=\"nc-orange_bg\">choriocarcinome</span></strong>, une cause rare d'hémorragie tardive.</p></div>"},{"i":"5fe4d8c8326e","n":34,"o":"34-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","q":"Face à une rétention placentaire partielle causant une HPP, quels sont les signes cliniques et le principal examen paraclinique à réaliser ?","a":"<div class=\"notion-course\"><ul><li><strong>Clinique :</strong> il n'y a pas de signe clinique spécifique. L'hémorragie persiste malgré les utérotoniques et peut favoriser une atonie ou une <span class=\"nc-red_bg nc-bold\">endométrite</span>.</li><li><strong>Paraclinique :</strong> l'<strong><span class=\"nc-blue_bg\">échographie pelvienne</span></strong> est l'examen de référence, systématique en cas d'hyperthermie ou d'hémorragie du post-partum.</li></ul></div>"},{"i":"9299c7f09f52","n":34,"o":"34-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","q":"Comment définit-on une hémorragie du post-partum (HPP) et quelle est son importance épidémiologique en France ?","a":"<div class=\"notion-course\"><p>Une HPP est définie par une <strong>perte sanguine ≥ 500 mL</strong> dans les suites de couches. C'est la <strong>première cause de mortalité maternelle en France</strong>, évitable dans 80 à 90 % des cas.</p></div>"},{"i":"a45128e9a9bd","n":34,"o":"34-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","q":"Quelles sont les trois fenêtres temporelles distinctes pour une hémorragie du post-partum et leurs causes dominantes associées ?","a":"<div class=\"notion-course\"><ul><li><strong>Hémorragie de la délivrance</strong> (post-partum immédiat &lt; 2h) : l'<strong><span class=\"nc-yellow_bg\">atonie utérine</span></strong> est la cause dominante (&gt; 50%).</li><li><strong>HPP précoce</strong> (entre 2h et 24h) : <strong><span class=\"nc-yellow_bg\">atonie utérine</span></strong>, <strong><span class=\"nc-orange_bg\">rétention placentaire</span> partielle</strong> (cotylédons, membranes) et <strong><span class=\"nc-orange_bg\">plaie de la filière génitale</span></strong>.</li><li><strong>HPP tardive/secondaire</strong> (entre J1 et M3) : <strong><span class=\"nc-orange_bg\">endométrite hémorragique</span></strong>, <strong><span class=\"nc-orange_bg\">retour de couches hémorragique</span></strong>, et plus rarement un <strong>choriocarcinome</strong>.</li></ul></div>"},{"i":"afb4cb0a6789","n":34,"o":"34-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","q":"Comment diagnostique-t-on une HPP due à une plaie de la filière génitale ?","a":"<div class=\"notion-course\"><ul><li><strong>Clinique :</strong> <strong>saignement de sang rouge vif</strong> avec un <strong><span class=\"nc-red nc-bold\">utérus</span> bien rétracté</strong> (globe de sécurité présent).</li><li><strong>Examen clé :</strong> une <strong>inspection sous valves systématique des voies génitales basses</strong> (déchirure du col, du vagin, du périnée) est indispensable.</li></ul></div>"},{"i":"e1f4ea1e8580","n":34,"o":"34-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","q":"Quels sont les signes cliniques et l'examen paraclinique clé en présence d'une atonie utérine post-partum ?","a":"<div class=\"notion-course\"><ul><li><strong>Clinique :</strong> <strong><span class=\"nc-blue_bg\">métrorragies</span> <span class=\"nc-yellow_bg nc-bold\">abondantes</span></strong> de sang rouge, <strong><span class=\"nc-red_bg\">absence de globe de sécurité</span></strong> (<span class=\"nc-red nc-bold\">utérus</span> <span class=\"nc-red nc-bold\">mou</span>, <span class=\"nc-red nc-bold\">non rétracté</span>, <span class=\"nc-red nc-bold\">dépassant l'ombilic</span>), pas de fièvre ni de <span class=\"nc-yellow_bg\">lochies</span> <span class=\"nc-yellow_bg nc-bold\">malodorantes</span>.</li><li><strong>Paraclinique :</strong> une <strong><span class=\"nc-blue_bg\">échographie pelvienne</span></strong> est réalisée pour éliminer une <span class=\"nc-orange nc-bold\">rétention</span> (membranes, cotylédons).</li></ul></div>"},{"i":"284b182f3dbe","n":34,"o":"34-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","q":"Pourquoi les D-dimères n'ont-ils pas de valeur d'exclusion pour une MTEV en post-partum ?","a":"<div class=\"notion-course\"><p>Les D-dimères sont <strong>physiologiquement élevés</strong> pendant le post-partum, ce qui en fait un examen sans valeur d'exclusion. La décision diagnostique repose donc directement sur la <strong>probabilité clinique</strong> et l'<strong>imagerie appropriée</strong> (écho-Doppler veineux, angio-TDM, TDM/IRM pelvienne ou IRM/angio-IRM cérébrale selon le cas).</p></div>"},{"i":"3618bd988020","n":34,"o":"34-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","q":"Quelle est la complication majeure de la thrombose veineuse en post-partum et comment la diagnostiquer ?","a":"<div class=\"notion-course\"><p>La complication redoutée est l'<strong>embolie pulmonaire (EP)</strong>. Toute <strong>dyspnée brutale</strong>, <strong>douleur thoracique</strong>, <strong>tachycardie</strong> ou <strong>hypoxémie</strong> du post-partum doit être considérée comme une EP jusqu'à preuve du contraire. La confirmation repose sur l'<strong>angio-TDM thoracique</strong>, ou une <strong>scintigraphie de ventilation/perfusion (V/Q)</strong> en cas de contre-indication au scanner.</p></div>"},{"i":"6207f4cc1747","n":34,"o":"34-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","q":"Quand suspecter une thrombophlébite pelvienne dans le post-partum et comment la diagnostiquer ?","a":"<div class=\"notion-course\"><p>Une <span class=\"nc-orange_bg\">thrombophlébite pelvienne</span> doit être suspectée devant une <strong>fièvre persistante</strong> malgré un traitement antibiotique pour une endométrite, associée à des <strong><span class=\"nc-blue_bg\">douleurs pelviennes</span> / lombo-abdominales diffuses</strong>. Le tableau clinique est souvent atypique et retardé. Le diagnostic est confirmé par <strong>TDM ou IRM pelvienne injectée</strong>.</p></div>"},{"i":"6c2f5c88ba6e","n":34,"o":"34-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","q":"Quels sont les facteurs de risque spécifiques de la maladie thromboembolique veineuse (MTEV) dans le post-partum ?","a":"<div class=\"notion-course\"><p>Les facteurs de risque incluent :</p><ul><li>Âge <strong>supérieur à 35 ans</strong>, <strong><span class=\"nc-red nc-bold\">multiparité</span></strong>, <strong>tabac</strong>.</li><li><strong><span class=\"nc-pink_bg\">Obésité</span></strong>, <strong><span class=\"nc-pink_bg\">varices</span></strong>, affections cardiaques.</li><li>Antécédents personnels de MTEV, <strong>thrombophilie</strong>.</li><li>Accouchement <strong>dystocique</strong> ou <strong>césarienne</strong> (surtout en urgence).</li><li><span class=\"nc-pink_bg\">Procréation médicalement assistée</span>.</li><li>Hémorragie du post-partum.</li></ul><p>Le post-partum est un facteur de risque majeur transitoire, surtout pendant les <strong>8 premières semaines</strong>.</p></div>"},{"i":"7e19062ce745","n":34,"o":"34-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","q":"Quels sont les signes cliniques orientant vers une thrombose veineuse profonde (TVP) des membres inférieurs dans le post-partum et quel est l'examen de référence ?","a":"<div class=\"notion-course\"><p>Les signes cliniques sont :</p><ul><li><strong>Douleur du mollet unilatérale</strong>.</li><li><strong>Œdème</strong>, <strong>augmentation du diamètre</strong> de la jambe, <strong>perte du ballant</strong> du mollet.</li><li>Signe de <strong>Homans</strong>.</li><li>Fébricule modéré, tachycardie inexpliquée.</li></ul><p>L'examen de référence est l'<strong>écho-Doppler veineux des membres inférieurs</strong>. Il est important de noter que les <strong>D-dimères sont peu utiles</strong> dans cette situation car physiologiquement élevés en post-partum.</p></div>"},{"i":"871e6781955f","n":34,"o":"34-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","q":"Quels signes cliniques évoquent une thrombose veineuse cérébrale dans le post-partum et quel est l'examen diagnostique clé ?","a":"<div class=\"notion-course\"><p>Les signes cliniques évocateurs sont des <strong>céphalées inhabituelles et persistantes</strong>, des <strong>crises convulsives</strong>, un <strong>déficit neurologique focal</strong>, des troubles de la conscience ou des signes d'hypertension intracrânienne (<strong>HTIC</strong>). L'examen diagnostique clé est l'<strong>IRM cérébrale</strong> associée à une <strong>angio-IRM veineuse</strong>.</p></div>"},{"i":"b38b24ecbdde","n":34,"o":"34-6","u":"Diagnostic positif","t":"Savoir diagnostiquer une thrombose veineuse dans le post-partum en fonction de l’étiologie","q":"Comment diagnostiquer une thrombose veineuse superficielle (TVS) dans le post-partum ?","a":"<div class=\"notion-course\"><p>La TVS se manifeste par un <strong>cordon induré douloureux</strong> sur un trajet variqueux, avec une <strong>inflammation locale</strong> et <strong>pas de fièvre élevée</strong>. Le diagnostic est principalement <strong>clinique</strong>, confirmé par un <strong>écho-Doppler veineux</strong> qui permet d'éliminer une extension profonde.</p></div>"},{"i":"33ae92f3e02d","n":34,"o":"34-1","u":"Dépister","t":"Connaître les éléments cliniques de surveillance pendant les suites de couches","q":"Que retenir concernant les éléments cliniques de surveillance pendant les suites de couches ?","a":"<div class=\"notion-course\"><p>Les <span>suites de couches</span> débutent <strong><span>2 h</span> après l’accouchement</strong> (fin du post-partum immédiat) et se terminent par le <span>retour de couches</span> (= reprise des menstruations). Durée moyenne <span><span class=\"nc-pink_bg\">6 semaines</span></span> (<span><span class=\"nc-pink_bg\">40 jours</span></span>). Une <span>hospitalisation</span> reste possible jusqu’au <span>12ᵉ jour</span> (prise en charge sécurité sociale).</p>\n\n      <p>L’examen quotidien recherche systématiquement les <strong><span <span=\"\">&gt;3</span> grands risques</strong> : <span>hémorragie</span>, <span>hyperthermie</span>, <span>thrombose veineuse</span>.</p>\n\n      <table>\n        <thead>\n          <tr><th>Paramètre</th><th>Ce que l’on cherche</th><th>Alarme si…</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Constantes</strong></td>\n            <td>Température (matin/soir), pouls, PA, FR, SpO₂, diurèse</td>\n            <td>T° &gt; <span>38 °C</span> à 2 reprises, <span>tachycardie</span>, <span>hypotension</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red_bg\">Utérus</span></strong></td>\n            <td>Hauteur utérine (involution ≈ <span>1 cm</span>/j), tonicité (globe de sécurité), sensibilité à la mobilisation</td>\n            <td><span class=\"nc-red_bg\">Utérus</span> <strong><span class=\"nc-red_bg nc-bold\">mal involué</span></strong>, <strong><span class=\"nc-red nc-bold\">mou</span></strong>, <strong>douloureux à la mobilisation</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg\">Lochies</span></strong></td>\n            <td>Quantité, odeur, aspect (sanglantes <span>J1</span>-J3 → séro-sanglantes → séreuses J10)</td>\n            <td><strong><span class=\"nc-yellow_bg nc-bold\">Abondantes</span></strong>, <strong><span class=\"nc-yellow_bg nc-bold\">malodorantes</span> / <span class=\"nc-yellow_bg\">fétides</span></strong>, hémorragiques tardives</td>\n          </tr>\n          <tr>\n            <td><strong>Périnée / cicatrice</strong></td>\n            <td><span class=\"nc-pink nc-bold\">Épisiotomie</span>, déchirures, cicatrice de <span class=\"nc-pink nc-bold\">césarienne</span> (rougeur, écoulement, désunion)</td>\n            <td><span><span class=\"nc-red nc-bold\">Abcès</span></span><span class=\"nc-red nc-bold\"> ou </span><strong><span class=\"nc-red nc-bold\">hématome de paroi</span></strong> après <span class=\"nc-pink nc-bold\">césarienne</span> · <strong>désunion</strong> après <span class=\"nc-pink nc-bold\">épisiotomie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Seins</strong></td>\n            <td>Montée laiteuse (<span>J2</span>-J3), engorgement, crevasses, mise au sein efficace</td>\n            <td><span>Placard</span> <span>inflammatoire</span>, <span>fièvre</span> + douleur localisée (lymphangite, galactophorite, <span>abcès</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Mollets / MI</strong></td>\n            <td>Douleur unilatérale, <span>œdème</span>, Homans, <span>dyspnée</span></td>\n            <td>Signes de <span>TVP</span> ou d’<span>embolie pulmonaire</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mictions / transit</strong></td>\n            <td>Reprise miction spontanée, <span>BU</span> si signes urinaires, reprise du transit</td>\n            <td>Rétention aiguë, <span>BU</span> positive, <span>constipation</span> opiniâtre</td>\n          </tr>\n          <tr>\n            <td><strong>Vécu psy</strong></td>\n            <td><em>Baby-blues</em> (<span>J3</span>-J10, transitoire) · <span>dépistage</span> <span>dépression</span> du post-partum</td>\n            <td>Symptômes durables &gt; <span>15 j</span>, idées suicidaires, troubles du lien mère-enfant</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Mesures préventives systématiques</h4>\n      <ul>\n        <li><strong><span class=\"nc-green_bg\">Lever précoce</span></strong> (<span>J0</span>) — prévention MTEV.</li>\n        <li><strong>Bas de contention</strong> de <span>classe 2</span> chez toutes les accouchées.</li>\n        <li><strong><span>HBPM</span> prophylactique</strong> selon le niveau de risque MTEV (voir obj-6).</li>\n        <li><strong>Ig anti-D</strong> si mère Rh- et enfant Rh+ : <span>200 µg</span> IM dans les <span>72 h</span> post-accouchement.</li>\n        <li><strong>Vaccinations à rattraper</strong> en post-partum : rubéole (si non immune), coqueluche, ROR (CI pendant <span>grossesse</span> mais OK en PP), varicelle.</li>\n        <li><strong>Rééducation périnéale</strong> prescrite à la visite postnatale (<span>6-8 semaines</span>).</li>\n        <li><strong>Contraception du post-partum</strong> proposée avant la sortie (cf. item 31 / 36).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Toute <span>fièvre</span> &gt; <span>38 °C</span>, toute douleur de mollet unilatérale, toute hémorragie ou anomalie des <span class=\"nc-yellow_bg\">lochies</span> en suites de couches doit déclencher <em>immédiatement</em> la triade diagnostique : <strong><span class=\"nc-red_bg nc-bold\">endométrite</span> ? thrombose ? hémorragie ?</strong> Ces 3 entités dominent la morbi-<span>mortalité</span> maternelle du post-partum.\n      </div></div>"},{"i":"73f8d59c4df1","n":34,"o":"34-2","u":"Diagnostic positif","t":"Savoir diagnostiquer une hyperthermie pendant les suites de couches en fonction de l’étiologie","q":"Que retenir concernant diagnostiquer une hyperthermie pendant les suites de couches en fonction de l’étiologie ?","a":"<div class=\"notion-course\"><p>L’<span><span class=\"nc-red nc-bold\">hyperthermie</span></span><span class=\"nc-red nc-bold\"> du post-partum</span> (T° &gt; <span>38 °C</span>) est <strong>fréquente</strong> et impose une démarche étiologique structurée. La <span>montée laiteuse</span> (<span>J2</span>-J3, fébricule modéré, seins tendus bilatéraux, pas d’autre signe) est un <strong>diagnostic d’élimination</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Étiologies à connaître (ordre décroissant)</h4>\n      <table>\n        <thead>\n          <tr><th>Étiologie</th><th>Tableau évocateur</th><th>Confirmation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-red_bg nc-bold\">Endométrite</span> aiguë du PP</span></strong><br><em>1ʳᵉ cause</em></td>\n            <td>\n              <ul>\n                <li>Début <span>J3-J5</span> (rarement avant)</li>\n                <li><span><span class=\"nc-blue_bg nc-bold\">Fièvre</span></span><span class=\"nc-blue_bg nc-bold\"> modérée</span> ≈ <span>38 °C</span></li>\n                <li><strong><span class=\"nc-yellow_bg\">Douleur à la mobilisation utérine</span></strong> ⭐ — signe principal</li>\n                <li><span class=\"nc-blue_bg\">Lochies </span><strong><span class=\"nc-blue_bg\">abondantes et malodorantes</span></strong> (<span class=\"nc-yellow_bg\">fétides</span> ± hémorragiques)</li>\n                <li><span class=\"nc-red_bg\">Utérus</span> <strong><span class=\"nc-red_bg nc-bold\">mal involué</span></strong>, <span class=\"nc-blue_bg\">col béant</span></li>\n                <li><strong>Germes</strong> : infection plurimicrobienne — <span><span class=\"nc-yellow_bg nc-bold\">SGA</span></span> (le + redouté), <span class=\"nc-purple_bg\">entérobactéries</span> (BGN), <span><span class=\"nc-purple_bg\">streptocoque</span></span><span class=\"nc-purple_bg\"> B</span>, <span class=\"nc-purple_bg\">entérocoques</span> ; anaérobies et intracellulaires (mycoplasme, chlamydia) plus rares</li>\n              </ul>\n            </td>\n            <td><span><span class=\"nc-blue_bg\">NFS</span></span><span class=\"nc-blue_bg\">/</span><span><span class=\"nc-blue_bg\">CRP</span></span>, <span><span class=\"nc-blue_bg\">ECBU</span></span>, examen bactério vaginal, <span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span> (<span class=\"nc-orange nc-bold\">rétention</span> ?) · <span><span class=\"nc-red nc-bold\">Hémocultures</span></span> si T° <span class=\"nc-red nc-bold\">&gt; </span><span><span class=\"nc-red nc-bold\">38,5 °C</span></span></td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-purple_bg\">Pyélonéphrite aiguë</span></span></strong> (≠ gravidique)</td>\n            <td>\n              <ul>\n                <li><span>Fièvre</span> + <span>frissons</span></li>\n                <li>Douleur lombaire unilatérale</li>\n                <li>Signes urinaires</li>\n              </ul>\n            </td>\n            <td><span>BU</span>, <span>ECBU</span>, <span><span class=\"nc-blue_bg\">NFS</span></span><span class=\"nc-blue_bg\">/</span><span><span class=\"nc-blue_bg\">CRP</span></span>, <span><span class=\"nc-red nc-bold\">hémocultures</span></span>, écho rénale</td>\n          </tr>\n          <tr>\n            <td><strong><span>Thrombophlébite des MI</span></strong></td>\n            <td>\n              <ul>\n                <li>Douleur de mollet unilatérale</li>\n                <li><span>Œdème</span>, augmentation du <span>diamètre</span></li>\n                <li>Signe de Homans</li>\n                <li><span><span class=\"nc-blue_bg nc-bold\">Fièvre</span></span><span class=\"nc-blue_bg nc-bold\"> modérée</span></li>\n              </ul>\n            </td>\n            <td>Écho-<span>doppler veineux</span> MI · <span>D-dimères</span> <em>peu utiles en PP</em></td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-orange_bg\">Thrombophlébite pelvienne</span></span></strong></td>\n            <td>\n              <ul>\n                <li><span>Fièvre</span> <em>persistante</em> sous ATB d’une endométrite</li>\n                <li><span class=\"nc-blue_bg\">Douleurs pelviennes</span> diffuses</li>\n                <li>Tableau souvent atypique</li>\n              </ul>\n            </td>\n            <td><strong><span>TDM</span> ou <span>IRM</span> pelvienne injectée</strong> — diagnostic de référence</td>\n          </tr>\n          <tr>\n            <td><strong><span>Complications de l’allaitement</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Engorgement</strong> : seins tendus bilatéraux, fébricule</li>\n                <li><strong>Lymphangite</strong> : <span>placard</span> rouge triangulaire, <span>fièvre</span> <span>39-40 °C</span>, ADP axillaire</li>\n                <li><strong>Galactophorite</strong> : douleur, lait <em>louche</em> au signe de Budin</li>\n                <li><strong><span>Abcès</span> du sein</strong> : <span>tuméfaction</span> fluctuante, <span>fièvre</span> élevée</li>\n              </ul>\n            </td>\n            <td>Clinique · <span>échographie</span> mammaire si suspicion d’<span>abcès</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Infection du site opératoire</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Après <span class=\"nc-pink nc-bold\">césarienne</span></strong> : <span><span class=\"nc-red nc-bold\">abcès</span></span><span class=\"nc-red nc-bold\"> ou hématome de paroi</span>, écoulement purulent</li>\n                <li><strong>Après <span class=\"nc-pink nc-bold\">épisiotomie</span></strong> : <strong><span class=\"nc-red nc-bold\">désunion de plaie</span></strong> ± <span class=\"nc-red nc-bold\">hématome périnéal</span></li>\n                <li><span>Alerte</span> : <span>purpura</span> ou décollement cutané rapidement évolutif → rechercher <strong>SGA</strong> ou <strong>S. aureus</strong></li>\n              </ul>\n            </td>\n            <td>Examen clinique, écho de paroi, prélèvements bactério</td>\n          </tr>\n          <tr>\n            <td><span>Montée laiteuse</span> <em>(diagnostic d’élimination)</em></td>\n            <td>Fébricule <span>J2</span>-J3 bilatéral, seins tendus, <strong>pas de douleur utérine, pas de signes urinaires, pas de signes de <span>TVP</span></strong></td>\n            <td>Diagnostic clinique <em>après avoir éliminé les autres causes</em></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Bilan <span>biologique</span> initial systématique</h4>\n      <ul>\n        <li><strong><span>NFS</span> + <span>CRP</span></strong></li>\n        <li><strong><span>BU</span> ± <span>ECBU</span></strong></li>\n        <li><strong>Prélèvement vaginal</strong> (examen bactériologique)</li>\n        <li><strong><span><span class=\"nc-red nc-bold\">Hémocultures</span></span></strong> si T° <span class=\"nc-red nc-bold\">&gt; </span><span><span class=\"nc-red nc-bold\">38,5 °C</span></span> (recherche listeria et SGA notamment)</li>\n        <li><strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span></strong> à la recherche d’une <span class=\"nc-orange nc-bold\">rétention</span> <span class=\"nc-orange nc-bold\">placentaire</span></li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"nc-red_bg nc-bold\">Endométrite</span> à <span class=\"nc-yellow_bg nc-bold\">SGA</span> ⚠️.</strong> <span><span class=\"nc-purple nc-bold\">Streptocoque</span></span><span class=\"nc-purple nc-bold\"> du groupe A</span> <span class=\"nc-yellow_bg\">= germe le plus redouté</span> du post-partum (tableau toxinique pouvant évoluer en quelques heures vers le <span>choc septique</span>). Y penser devant toute <span class=\"nc-red_bg nc-bold\">endométrite</span> d’<span>évolution</span> <span class=\"nc-blue_bg nc-bold\">rapide</span>, <span>hyperthermie</span> élevée, douleurs intenses, signes cutanés. <span><span class=\"nc-red nc-bold\">Hémocultures</span></span> + écouvillonnage vaginal pour test <span class=\"nc-blue_bg nc-bold\">rapide</span>. <span>Hospitalisation</span>, β-lactamines à forte dose ± <span>clindamycine</span>.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Si <span>fièvre</span> persistante sous ATB :</strong> évoquer en priorité <strong>2 diagnostics</strong> →\n        <ul>\n          <li><strong><span class=\"nc-orange_bg\">Thrombophlébite pelvienne</span></strong><span class=\"nc-orange_bg\"> associée</span> (<span><span class=\"nc-blue_bg\">TDM</span></span><span class=\"nc-blue_bg\">/</span><span><span class=\"nc-blue_bg\">IRM</span></span><span class=\"nc-blue_bg\"> injectée</span>).</li>\n          <li><strong><span class=\"nc-orange_bg\">Rétention de fragments placentaires</span></strong> (<span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span>).</li>\n        </ul>\n      </div></div>"},{"i":"2cd763936436","n":34,"o":"34-3","u":"Prise en charge","t":"Savoir traiter une hyperthermie pendant les suites de couches en fonction de l’étiologie","q":"Que retenir concernant traiter une hyperthermie pendant les suites de couches en fonction de l’étiologie ?","a":"<div class=\"notion-course\"><p>La prise en charge est <strong>étiologique</strong>. <span><span class=\"nc-green_bg\">Hospitalisation</span></span><span class=\"nc-green_bg\"> habituelle</span> pour toute <span>fièvre</span> du post-partum &gt; <span>38,5 °C</span> ou avec <span>signes de gravité</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Endométrite aiguë du PP</h4>\n      <table>\n        <thead><tr><th>Volet</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Orientation</strong></td>\n            <td><span>Hospitalisation</span> 🏥</td>\n          </tr>\n          <tr>\n            <td><strong><span>Antibiothérapie</span></strong></td>\n            <td>\n              <ul>\n                <li><span>Amoxicilline + acide clavulanique</span> pendant <span><span class=\"nc-pink nc-bold\">5-10 jours</span></span></li>\n                <li>Voie IV initialement, relai per os après normalisation thermique</li>\n                <li>Adaptation à l’<span>antibiogramme</span> (prélèvement vaginal, <span><span class=\"nc-red nc-bold\">hémocultures</span></span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Utérotoniques</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-pink nc-bold\">Oxytocine</span></span> ou <span><span class=\"nc-pink nc-bold\">misoprostol</span></span> pour favoriser la rétraction utérine</li>\n                <li><strong>Non systématique</strong>, à débuter en cas d’<strong><span class=\"nc-orange_bg\">endométrite </span><span><span class=\"nc-orange_bg\">hémorragique</span></span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Évolution</span></strong></td>\n            <td>\n              <ul>\n                <li>Généralement rapidement favorable sous traitement adapté</li>\n                <li><strong>Si <span>fièvre</span> persistante</strong> → 2 diagnostics prioritaires :\n                  <ul>\n                    <li><span class=\"nc-orange_bg\">Thrombophlébite pelvienne</span> (<span><span class=\"nc-blue_bg\">TDM</span></span><span class=\"nc-blue_bg\">/</span><span><span class=\"nc-blue_bg\">IRM</span></span><span class=\"nc-blue_bg\"> injectée</span>)</li>\n                    <li><span class=\"nc-orange_bg\">Rétention de fragments placentaires</span> (<span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span>)</li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Autres étiologies — schémas thérapeutiques</h4>\n      <table>\n        <thead><tr><th>Étiologie</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-purple_bg\">Pyélonéphrite</span></span><span class=\"nc-purple_bg\"> aiguë</span></strong></td>\n            <td>\n              <ul>\n                <li>C<span <span=\"\">&gt;3</span>G IV (<span>céfotaxime</span> / <span>ceftriaxone</span>) ± aminoside</li>\n                <li>Relai per os adapté à l’<span>antibiogramme</span> · durée <span>10-14 jours</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Thrombophlébite des MI</strong></td>\n            <td><span>HBPM</span> curative + <span class=\"nc-green_bg\">bas de contention</span> <span>classe 3</span> (cf. obj-6)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Thrombophlébite pelvienne</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>ATB IV adaptée</strong> (poursuite/escalade)</li>\n                <li><strong>Héparinothérapie curative</strong> ± relai <span>AVK</span> selon localisation et étendue</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Engorgement / lymphangite</strong></td>\n            <td>\n              <ul>\n                <li>Poursuite de l’<span>allaitement</span> (sauf <span>abcès</span> patent)</li>\n                <li>Tétées fréquentes, vidange complète, <span>AINS</span> local / <span>paracétamol</span></li>\n                <li>Si lymphangite : ATB anti-staphylococcique (oxacilline, cloxacilline) <span>7-10 jours</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Galactophorite</strong></td>\n            <td>ATB anti-staph + suspension transitoire de l’<span>allaitement</span> du côté atteint</td>\n          </tr>\n          <tr>\n            <td><strong><span>Abcès</span> du sein</strong></td>\n            <td>\n              <ul>\n                <li><strong><span>Drainage</span> chirurgical</strong> ou <span>ponction</span> écho-guidée</li>\n                <li>ATB anti-staphylococcique</li>\n                <li><span>Allaitement</span> <span>contre-indiqué</span> côté atteint pendant la phase aiguë</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Infection de cicatrice de <span class=\"nc-blue_bg\">césarienne</span></strong></td>\n            <td>\n              <ul>\n                <li>Évacuation d’un hématome / mise à plat d’un <span>abcès</span></li>\n                <li>ATB anti-staphylococcique adaptée</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Désunion d’épisiotomie</strong></td>\n            <td>\n              <ul>\n                <li>Soins locaux antiseptiques, cicatrisation dirigée</li>\n                <li><span>Reprise chirurgicale</span> différée si nécessaire</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Montée laiteuse</span></td>\n            <td>Pas d’ATB — <span>surveillance</span> simple, <span>paracétamol</span>, vidange du sein</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Signal d’alarme.</strong> Toute infection cutanée rapidement évolutive avec <strong><span>purpura</span></strong> ou <strong>décollement</strong> doit faire évoquer et traiter en <span>urgence</span> un <span>SGA</span> ou un <span>S. aureus</span> (risque de <span>fasciite nécrosante</span> / <span>sepsis</span> foudroyant) : <span>hospitalisation</span>, β-lactamines IV à forte dose ± <span>clindamycine</span>, avis chirurgical.\n      </div></div>"},{"i":"bbbbfcb47ff7","n":34,"o":"34-5","u":"Prise en charge","t":"Savoir traiter une hémorragie génitale pendant les suites de couches en fonction de l’étiologie","q":"Que retenir concernant traiter une hémorragie génitale pendant les suites de couches en fonction de l’étiologie ?","a":"<div class=\"notion-course\"><p>Toute HPP est une <span>urgence vitale</span>. La prise en charge est <strong>simultanément maternelle (hémodynamique)</strong> et <strong>obstétricale (geste hémostatique)</strong>, escaladée par paliers de 15-<span <span=\"\">&gt;<span class=\"nc-pink nc-bold\">30</span></span><span class=\"nc-pink nc-bold\"> minutes</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Hémorragie de la délivrance (post-partum immédiat &lt; <span>2 h</span>)</h4>\n      <table>\n        <thead><tr><th>Temps</th><th>Actions</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1ᵉʳ temps</strong></td>\n            <td>Prévenir <strong>tous les intervenants</strong> (anesthésiste, sage-femme, obstétricien) sans délai</td>\n          </tr>\n          <tr>\n            <td><strong>2ᵉ temps</strong></td>\n            <td>\n              <ul>\n                <li>Monitorage (pouls, PA, SpO₂)</li>\n                <li>VVP de gros calibre, remplissage cristalloïdes</li>\n                <li>Vérification groupe + RAI &lt; <span>3 jours</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3ᵉ temps — geste obstétrical</strong></td>\n            <td>\n              <ul>\n                <li>Si hémorragie <strong>avant</strong> expulsion du placenta → <strong><span class=\"nc-yellow_bg\">délivrance artificielle</span></strong><span class=\"nc-yellow_bg\"> en </span><span><span class=\"nc-yellow_bg\">urgence</span></span></li>\n                <li>Si hémorragie <strong>après</strong> expulsion → <strong><span class=\"nc-pink nc-bold\">révision utérine</span></strong> d’emblée</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>4ᵉ temps — hémostase</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-green_bg\">Massage utérin énergique</span> ⭐</strong> jusqu’à obtenir un <strong><span class=\"nc-green nc-bold\">globe tonique</span></strong></li>\n                <li><strong>Inspection sous valves</strong> → éliminer une déchirure cervicale / vaginale</li>\n                <li><span>Oxytocine IVL 10 UI</span>, renouvelable 1×</li>\n                <li>Sac collecteur sous les fesses (estimation des pertes)</li>\n                <li><span class=\"nc-green_bg\">Sondage urinaire à demeure</span> (vessie vide = bon globe)</li>\n                <li><span class=\"nc-green_bg\">Suture des déchirures périnéales éventuelles</span></li>\n                <li><span><span class=\"nc-pink_bg\">Antibioprophylaxie</span></span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Si persistance des saignements à <span>15-30 min</span> :</strong>\n        <ul>\n          <li><span>Sulprostone</span> (prostaglandine) à la seringue électrique, puis relai <span class=\"nc-pink nc-bold\">oxytocine</span> <span>2 h</span></li>\n          <li><span>Acide tranexamique</span> <span>1 g</span> IV</li>\n          <li>VVP gros calibre, <span>oxygénothérapie</span>, remplissage par macromolécules</li>\n          <li><strong>Transfusion CGR + PFC</strong> selon pertes et coagulation</li>\n          <li><span>NFS</span> + <span class=\"nc-blue_bg\">bilan d’hémostase</span> en <span>urgence</span> (recherche <span>CIVD</span>)</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>Si hémorragie persistante malgré la PEC initiale :</strong>\n        <ul>\n          <li><strong>Embolisation artérielle sélective</strong> — 3 prérequis : patiente stable, <span class=\"nc-green_bg\">radiologue entraîné disponible</span>, unité d’embolisation à proximité</li>\n          <li><strong><span>Chirurgie</span></strong> : <span class=\"nc-pink_bg nc-bold\">ligature</span> des artères utérines / hypogastriques, <span class=\"nc-pink_bg\">techniques de</span> compression utérine (B-Lynch, Cho)</li>\n          <li><strong>En dernier recours — <span class=\"nc-red_bg\">hystérectomie d’hémostase</span></strong>, à ne pas retarder si <span><span class=\"nc-red nc-bold\">hémodynamique instable</span></span> ou <span><span class=\"nc-red nc-bold\">CIVD installée</span></span></li>\n        </ul>\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">Hémorragies du post-partum (&gt; <span>2 h</span>) — traitement étiologique</h4>\n      <table>\n        <thead><tr><th>Étiologie</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Atonie utérine</strong></td>\n            <td>\n              <ul>\n                <li>Massage utérin + <span>utérotoniques</span> (<span class=\"nc-pink nc-bold\">oxytocine</span>, prostaglandines)</li>\n                <li>Si échec → escalade comme HPP de la délivrance</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-purple_bg\">Rétention placentaire</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-yellow_bg\">Révision utérine prudente</span></strong> (curette mousse sous contrôle échographique — <span class=\"nc-red_bg\">utérus</span> fragile)</li>\n                <li><span class=\"nc-pink_bg\">Résection hystéroscopique</span> parfois</li>\n                <li><strong><span>Antibioprophylaxie</span></strong> systématique</li>\n                <li>Si hémorragie importante : <strong><span class=\"nc-pink nc-bold\">tamponnement intra-utérin</span></strong> (Bakri) ou embolisation</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Plaie de la filière génitale</span></strong></td>\n            <td>Suture après exposition sous valves, au bloc si nécessaire</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Endométrite </span><span><span class=\"nc-orange_bg\">hémorragique</span></span></strong></td>\n            <td>\n              <ul>\n                <li><span>Amoxicilline + acide clavulanique</span> IV</li>\n                <li><strong>Utérotoniques systématiques</strong> (<span class=\"nc-pink nc-bold\">oxytocine</span> ± <span class=\"nc-pink nc-bold\">misoprostol</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Retour de couches </span><span><span class=\"nc-orange_bg\">hémorragique</span></span></strong></td>\n            <td>\n              <ul>\n                <li>Pilule œstrogénique (en l’absence de CI)</li>\n                <li><span>Surveillance</span> simple si pertes modérées</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Choriocarcinome</span></strong></td>\n            <td>Dosage hCG → orientation oncologique spécialisée (<span>chimiothérapie</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Prévention systématique de l’HPP — APO.</strong> <span><span class=\"nc-pink nc-bold\">Oxytocine</span> 5-10 UI IVL</span> dès la sortie de l’enfant, sac de recueil dès l’expulsion, <span>surveillance</span> <span>2 h</span> en salle de <span class=\"nc-blue_bg\">travail</span>, <span class=\"nc-pink nc-bold\">délivrance artificielle</span> si non-décollement <span class=\"nc-orange nc-bold\">placentaire</span> à <span>30 min</span>.\n      </div></div>"},{"i":"b3c828532759","n":34,"o":"34-7","u":"Prise en charge","t":"Savoir traiter une thrombose veineuse dans le post-partum en fonction de l’étiologie","q":"Que retenir concernant traiter une thrombose veineuse dans le post-partum en fonction de l’étiologie ?","a":"<div class=\"notion-course\"><p>Deux axes : <strong>prophylaxie</strong> (stratifiée selon le niveau de risque MTEV) et <strong>traitement curatif</strong> (selon la localisation).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">A. Prophylaxie de la MTEV en post-partum</h4>\n      <table>\n        <thead>\n          <tr><th>Niveau de risque</th><th>Définition</th><th>Prophylaxie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Risque majeur</span></strong></td>\n            <td>\n              <ul>\n                <li>ATCD de <strong><span class=\"nc-red nc-bold\">MTEV multiples</span></strong></li>\n                <li><strong><span class=\"nc-red nc-bold\">Thrombophilie traitée au long cours</span></strong> par <span>anticoagulant</span> (même avant la <span>grossesse</span>)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Bas de contention</span></li>\n                <li><strong><span>AVK</span> pendant <span class=\"nc-pink nc-bold\">≥ </span><span><span class=\"nc-pink nc-bold\">3 mois</span></span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risque élevé</strong></td>\n            <td>\n              <ul>\n                <li>ATCD MTEV sans FR retrouvé</li>\n                <li>ATCD MTEV lors d’une <span>grossesse</span> antérieure ou d’un traitement œstrogénique</li>\n                <li>ATCD MTEV + 1 FR <span>biologique</span> (déficit AT, <span class=\"nc-red\">SAPL</span>, mutation <span class=\"nc-red\">20210A</span> homozygote ou <span>FV</span> <span class=\"nc-red\">Leiden</span>, anomalies hétérozygotes combinées)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Bas de contention</span></li>\n                <li><strong><span><span class=\"nc-pink nc-bold\">HBPM</span></span><span class=\"nc-pink nc-bold\"> à dose prophylactique forte</span></strong> pendant <span>6-8 semaines</span><br><em><span>énoxaparine</span> 4 <span>000 UI</span>/j ou daltéparine 5 <span>000 UI</span>/j</em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risque modéré</strong></td>\n            <td>\n              <ul>\n                <li>ATCD MTEV avec FR temporaire au moment de l’épisode antérieur</li>\n                <li>ATCD MTEV + FR <span>biologique</span> (autre que ceux du risque élevé)</li>\n                <li>FR <span>biologique</span> asymptomatique dépisté dans le cadre d’une MTEV familiale</li>\n                <li><strong><span class=\"nc-pink_bg\">Césarienne en </span><span><span class=\"nc-pink_bg\">urgence</span></span></strong></li>\n                <li>Césarienne + <span>chirurgie</span> pelvienne majeure associée</li>\n                <li>Présence de ≥ <span>3 FR faibles</span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Bas de contention</span></li>\n                <li><strong><span>HBPM</span> à dose prophylactique forte</strong> pendant <span>6-8 semaines</span> (dose et durée pouvant être réduites selon le niveau de risque)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risque faible</strong></td>\n            <td>\n              &lt; 3 des FR suivants :\n              <ul>\n                <li><span class=\"nc-pink_bg\">Âge &gt;</span><span><span class=\"nc-pink_bg\"> 35 ans</span></span>, <span><span class=\"nc-pink_bg\">obésité</span></span> (IMC &gt; 30 ou poids &gt;<span> 80 kg</span>), <span class=\"nc-pink_bg\">varices</span>, <span><span class=\"nc-pink_bg\">HTA</span></span></li>\n                <li>Facteurs obstétricaux : <span class=\"nc-blue_bg\">césarienne</span>, <span class=\"nc-blue_bg\">multiparité &gt; 4</span>, <span class=\"nc-blue_bg\">prééclampsie</span>, <span class=\"nc-blue_bg\">alitement strict prolongé</span>, HPP…</li>\n                <li><span class=\"nc-orange_bg\">Maladie thrombogène sous-jacente</span> (<span>syndrome néphrotique</span>, <span>MICI</span> en poussée, infection systémique…)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Bas de contention</span></li>\n                <li><strong>Pas d’<span>anticoagulant</span></strong> ❌</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">B. Traitement curatif selon la localisation</h4>\n      <table>\n        <thead><tr><th>Localisation</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Thrombose veineuse superficielle</strong></td>\n            <td>\n              <ul>\n                <li><span>AINS</span> locaux + <span class=\"nc-green_bg\">contention veineuse</span></li>\n                <li>± <span class=\"nc-pink_bg\">Anticoagulation</span> selon extension et localisation</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Thrombose veineuse profonde</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-pink_bg\">Anticoagulation</span> curative</strong> (<span>HBPM</span>, puis relai <span>AVK</span> compatible avec l’<span>allaitement</span>)</li>\n                <li><span class=\"nc-green_bg\">Contention veineuse</span> <strong><span>classe 3</span></strong></li>\n                <li>Durée : <span>3-6 mois</span> minimum selon contexte</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Thrombophlébite pelvienne</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-pink_bg\">ATB IV adaptée</span></strong></li>\n                <li><strong>Héparinothérapie curative</strong> ± relai <span>AVK</span> selon localisation et étendue</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Thrombose veineuse cérébrale</strong></td>\n            <td>\n              <ul>\n                <li><strong><span>HBPM</span> curative</strong> puis relai <span><span class=\"nc-pink_bg\">AVK</span></span> ≥ <span>6 mois</span></li>\n                <li><span class=\"nc-pink_bg\">± mannitol / anti-épileptique</span> selon signes neurologiques</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:var(--ink);\">C. Choix de l’<span>AVK</span> pendant l’<span>allaitement</span></h4>\n      <table>\n        <thead><tr><th>Molécule</th><th>Allaitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span><span class=\"nc-red nc-bold\">Fluindione</span></span></td>\n            <td><span>❌ Contre-indiquée</span> — non utilisable pendant l’<span>allaitement</span></td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-pink_bg\">Warfarine</span></span>, <span><span class=\"nc-pink_bg\">acénocoumarol</span></span></td>\n            <td>✅ Possibles — pas de <span>diffusion</span> dans le lait maternel</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> En post-partum la <strong><span><span class=\"nc-pink_bg\">warfarine</span></span></strong> et l’<strong><span class=\"nc-pink_bg\">acénocoumarol</span></strong> sont les <span><span class=\"nc-pink_bg\">AVK</span></span> de choix si <span>allaitement</span>, jamais la <span><span class=\"nc-red nc-bold\">fluindione</span></span>. Les <span>HBPM</span> restent l’option la plus utilisée en pratique en relai initial.\n      </div></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181799a94ece23f012e0b?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."},"liensGlobaux":[{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"},{"href":"https://cngof.fr/app/uploads/2025/11/Hemorragie202014_PP.pdf","label":"CNGOF · Hémorragies du post-partum, 2014"},{"href":"https://iris.who.int/bitstreams/cd3655a4-b990-49ed-b293-618b37c5444a/download","label":"OMS · Acide tranexamique et HPP, 2017"}]};
